INSERT INTO `products` (`id`, `product_name`, `slug`, `type_id`, `price`, `capacity`, `alcohol`, `origin`, `manufacturer_id`, `category_id`, `detail`, `create_at`, `update_at`, `is_delete`, `quantity`, `status`) VALUES ('VD/0281', 'Rượu Vang Đỏ Château Corbin 2014', 'rượu-vang-đỏ-château-corbin-2014', 1, 2002000.00, '750ML', 14.5, 'Pháp', 1, 1, 'Château Corbin 2014 – Dòng vang hảo hạng từ Saint-Émilion Grand Cru\r\nNằm phía đông tỉnh Gironde tại vùng Bordeaux,\r\nSaint-Émilion Grand Cru\r\nnổi bật lên là khu vực làm vang đặc biệt với truyền thống làm vang lâu đời bậc nhất của nước Pháp. Đây cũng chính là cái nôi của những dòng rượu vang đẳng cấp mang hương vị thượng hạng được cả thế giới săn lùng.\r\nSở hữu vị trí đắc địa bên bờ phải của sông Dordogne bao quanh là những ruộng nho trải dài bên sườn đồi và thung lũng thoải,\r\nSaint-Émilion Grand Cru\r\nthừa hưởng nhiều lợi thế về thổ nhưỡng cùng khí hậu ôn hòa ấm áp gần như quanh năm tạo điều kiện phát triển tốt cho các ruộng nho.\r\nĐặc trưng vùng là sự đa dạng về thổ nhưỡng, từ đất đá vôi phù sa cho đến đất phù sa, đất sỏi và đất cát. Sự đa dạng thể hiện trên chất đất từng thửa ruộng của từng nhà sản xuất cho dù nằm cạnh nhau nhưng lại có rất nhiều sự khác biệt. Điều này tạo ra sự phong phú và sự đa dạng trong rượu vang của\r\nSaint-Émilion Grand Cru\r\n, mang lại tính phức tạp và độ sâu cho mỗi dòng rượu vang đỏ. Những khu vực có thổ nhưỡng tốt nhất hầu hết đều nằm trên các cao nguyên đá vôi với đất sét mềm, sỏi, cát và trầm tích sắt như Château Troplong Mondot.\r\nVới các lớp đá vôi khổng lồ cùng trầm tích, những dòng vang thuộc các Château trên cao nguyên có sự phong phú, kết cấu tốt và tươi mát vị khoáng chất.  Merlot là giống nho chủ đạo tại Saint-Émilion, sau đó là Cabernet Franc và Cabernet Sauvignon. Merlot đem lại hương vị mềm mại, tinh tế, Cabernet Franc mang đến sắc thái mạnh mẽ, vị chát dày dặn cùng với Cabernet Sauvignon, hương vị quả đỏ đậm đà trở nên nổi bật.\r\nRượu vang đỏ Saint-Émilion\r\nđiển hình có chất vị đậm đà, đầy đặn và vô cùng tinh tế.\r\nBên cạnh lợi thế về vị trí và sự đa dạng thổ nhưỡng, tại\r\nSaint-Émilion Grand Cru\r\n, bất cứ nhà sản xuất nào cũng bắt buộc đảm bảo tuân thủ nghiêm ngặt các nguyên tắc chất lượng cao để đảm bảo rằng chỉ những loại rượu vang tốt nhất mới được xếp vào phân hạng “Grand Cru”. Bộ quy tắc này bao gồm quy định về phương pháp trồng, sản xuất, lựa chọn nho và quy trình kiểm soát chất lượng. Tổng hòa những yếu tố trên, không thể phủ nhận\r\nSaint-Émilion Grand Cru\r\nchính là miền đất hứa nơi giới tinh hoa có thể tìm thấy những chai vang phức hợp, tinh tế và đa chiều, với khả năng lưu trữ lâu dài và khả năng phát triển vượt trội theo thời gian.', '2025-12-18 21:47:17', '2026-01-28 02:19:05', 1, 47, NULL);
INSERT INTO `products` (`id`, `product_name`, `slug`, `type_id`, `price`, `capacity`, `alcohol`, `origin`, `manufacturer_id`, `category_id`, `detail`, `create_at`, `update_at`, `is_delete`, `quantity`, `status`) VALUES ('VD/1088', 'Rượu Vang Đỏ Haut Roc Blanquant 2016', 'ruou-vang-do-haut-roc-blanquant-2016', 1, 2178000.00, '750ML', 14.5, 'Pháp', 2, 1, 'Château Haut Roc Blanquant – Dòng vang “third-wine” danh tiếng của Château Bélair-Monange\r\nHaut Roc Blanquant\r\nlà dòng rượu vang “third-wine” nổi tiếng từ\r\nChâteau Bélair-Monange\r\nđược đặt tên theo mảnh đất lịch sử của vườn nho\r\nChâteau Bélair-Monange\r\n. Hàm nghĩa “đá trắng” của\r\nHaut Roc Blanquant\r\nđã thay rượu nhấn mạnh địa chất của vườn nho nơi rượu được tạo nên. Kể từ niên vụ 2014,\r\nHaut Roc Blanquant\r\nđược phát hành với số lượng rất hạn chế khi các nhà làm vang quyết định thắt chặt yêu cầu tuyển chọn nho làm rượu nhằm mang đến những dòng vang quyến rũ, sang trọng và có thể thưởng thức ngay từ khi còn trẻ. Dẻo dai, tươi sáng và hấp dẫn,\r\nHaut Roc Blanquant\r\nđã xuất sắc lột tả chất vị tinh tế của terroir vùng\r\nSaint-Émilion\r\nlẫn phong cách làm rượu của Jean-Pierre Moueix và nhà sản xuất\r\nChâteau Bélair-Monange\r\n.\r\nKhám phá Château Bélair-Monange – Điền trang nổi tiếng vùng Saint-Émilion\r\nNằm trên ngọn đồi cao nhất của cao nguyên đá vôi nổi tiếng\r\nSaint-Émilion\r\n, Château Bélair từ lâu đã được biết đến như một trong những nhà làm rượu xuất sắc nhất khu vực. Nhiều tài liệu ghi chép đã ghi lại sự tồn tại của\r\nChâteau Bélair\r\ntừ thời La Mã cổ đại. Năm 1850, điền trang danh tiếng này vinh dự được Cocks & Feret xếp hạng là nhà sản xuất rượu vang hàng đầu tại Saint-Émilion, với danh tiếng và chất lượng được duy trì và bảo chứng qua hàng trăm năm.\r\nNhà làm vang huyền thoại Jean-Pierre Moueix đã mua lại\r\nChâteau Bélair-Monange\r\ntừ năm 2008 và chính thức đổi tên điền trang thành Château Bélair-Monage. Ngoài hàm nghĩa “thiên thần của tôi”, cụm từ Monange còn là tên thời trẻ của mẹ Jean-Pierre Moueix. Tên gọi\r\nChâteau Bélair-Monane\r\ndo đó được xem như cách tượng đài vang Pháp tỏ lòng tri ân với mẹ mình, người lúc sinh thời vốn luôn coi\r\nSaint-Émilion\r\nnhư ngôi nhà thứ 2 của bà. Hàng loạt dự án cải tạo hệ thống vườn nho, nhà máy rượu, hầm rượu lẫn lâu đài đã được Jean-Pierre Moueix thực hiên, với nỗ lực đưa Château Bélair-Monage về trạng thái nguyên bản như khi vừa thành lập.\r\nXét về thổ nhưỡng,\r\nChâteau Bélair-Monange\r\nnằm trên thổ nhưỡng hoàn hảo, nơi hội tụ hai chất đất tốt nhất vùng\r\nSaint-Émilion\r\nđể tạo điều kiện sản xuất nên những dòng rượu vang mang chất lượng tuyệt hảo: đất đá phấn đem lại hương vị tươi mát, khoáng đạt, hương thơm tinh tế kéo dài; chất đất sét xanh quý giá đem lại hương vị đậm đầy, dư vị dài lâu và nét tinh tế hiếm có.', '2025-12-18 21:47:17', NULL, 0, 21, NULL);
