INSERT INTO `products` (`id`, `product_name`, `slug`, `type_id`, `price`, `capacity`, `alcohol`, `origin`, `manufacturer_id`, `category_id`, `detail`, `create_at`, `update_at`, `is_delete`, `quantity`, `status`) VALUES ('VD/0682', 'Rượu vang đỏ Louis Latour Bourgogne Pinot Noir', 'ruou-vang-do-louis-latour-bourgogne-pinot-noir', 1, 1038000.00, '750ML', 13, 'Pháp', 7, 5, '', '2025-12-18 21:47:17', NULL, 0, 46, NULL);
INSERT INTO `products` (`id`, `product_name`, `slug`, `type_id`, `price`, `capacity`, `alcohol`, `origin`, `manufacturer_id`, `category_id`, `detail`, `create_at`, `update_at`, `is_delete`, `quantity`, `status`) VALUES ('VD/0628', 'Rượu vang đỏ Louis Latour Domaine De Valmoissine', 'ruou-vang-do-louis-latour-domaine-de-valmoissine', 1, 532000.00, '750ML', 0, 'Pháp', 7, 6, '', '2025-12-18 21:47:17', NULL, 0, 35, NULL);
INSERT INTO `products` (`id`, `product_name`, `slug`, `type_id`, `price`, `capacity`, `alcohol`, `origin`, `manufacturer_id`, `category_id`, `detail`, `create_at`, `update_at`, `is_delete`, `quantity`, `status`) VALUES ('VD/1602', 'Rượu vang đỏ Domaine Faiveley Bourgogne Pinot Noir 2023', 'ruou-vang-do-domaine-faiveley-bourgogne-pinot-noir-2023', 1, 1364000.00, '750ML', 13, 'Pháp', 8, 5, 'Domaine Faiveley – Điền trang vang Pháp danh giá\r\nDomaine Faiveley – Điền trang vang Pháp danh giá hàng đầu\r\nDomaine Faiveley\r\nlà nhà sản xuất rượu vang danh tiếng có trụ sở đặt tại Nuits-Saint-Georges, Bourgogne. Thương hiệu do Pierre Faiveley thành lập từ năm 1825 và đã trải qua 7 thế hệ gia đình Faiveley điều hành, phát triển. Domaine Faiveley hiện do thế hệ Faiveley thứ 7 là Eve cùng em gái là Erwan Faiveley quản lý.\r\nTại\r\nBourgogne\r\n, Domaine Faiveley là một trong những nhà sản xuất lớn mạnh nhất, sở hữu hơn 120 hecta vườn nho, với 12 hecta được xếp hạng Grand Cru và 22 hecta được xếp hạng Premier Cru. Dưới sự dẫn dắt và lãnh đạo của chị em Eve và Erwan Faiveley, Domaine Faiveley cam kết phát triển nghề trồng nho bền vững và tạo nên những dòng rượu vang mạnh mẽ, tinh tế và thanh lịch, được tín đồ yêu vang và chuyên gia rượu vang thế giới đánh giá cao.\r\nTận hưởng hương vị rượu vang Domaine Faiveley Bourgogne Pinot Noir 2023 cùng ly RIEDEL Performance Pinot Noir\r\nRượu vang đỏ Domaine Faiveley Bourgogne Pinot Noir 2023\r\nlan tỏa hương thơm quyến rũ của trái cây đỏ, hòa quyện cùng cấu trúc đậm đà và vị chát mềm mại, dễ chịu. Với mức giá chỉ hơn 1 triệu đồng, rượu là lựa chọn hoàn hảo để thưởng thức hàng ngày lẫn làm quà tặng cho các đối tác, khách hàng, cấp trên trong những dịp đặc biệt.\r\nDomaine Faiveley Bourgogne Pinot Noir 2023 sở hữu hương vị ấn tượng\r\nĐể thưởng thức trọn vẹn\r\nDomaine Faiveley Bourgogne Pinot Noir 2023\r\n– dòng\r\nvang đỏ\r\nthanh lịch từ vùng Bourgogne, không lựa chọn nào lý tưởng hơn\r\nly pha lê RIEDEL Performance Pinot Noir\r\n. Với thiết kế bầu ly rộng, miệng loe nhẹ giúp lan tỏa và tập trung hương thơm, cùng phần gờ quang học độc đáo tạo hiệu ứng thẩm mỹ và tăng cường cảm nhận vị giác, dòng ly này được nghiên cứu sản xuất để làm nổi bật cấu trúc tinh tế, sắc thái thanh thoát đặc trưng của\r\nPinot Noir\r\n. Sự kết hợp giữa Domaine Faiveley và RIEDEL Performance không chỉ là nghệ thuật thưởng vang, mà còn là trải nghiệm đánh thức mọi giác quan.\r\nMua sắm rượu vang Domaine Faiveley Bourgogne Pinot Noir 2023 tại Grand Cru – Modern Wine Bar\r\nVới danh mục rượu vang đa dạng, bao gồm hơn 1500 sản phẩm\r\nvang nhập khẩu\r\ntừ các nhà sản xuất và thương hiệu vang danh tiếng trên toàn thế giới,\r\nGrand Cru – Modern Wine Bar\r\ntự hào là đơn vị nhập khẩu và phân phối các sản phẩm rượu vang từ thương hiệu Domaine Faiveley chính hãng. Chúng tôi cam kết mang tới sản phẩm với chất lượng và mức giá hấp dẫn nhất thị trường, phù hợp để làm quà tặng trong những dịp đặc biệt lẫn thưởng thức hàng ngày.\r\nQuý khách hàng có nhu cầu mua sắm rượu vang Domaine Faiveley vui lòng liên hệ với chúng tôi qua Hotline 090 479 90 09 hoặc Fanpage Grand Cru – Modern Wine Bar để được tư vấn và đặt hàng các sản phẩm nhanh chóng nhất.', '2025-12-18 21:47:17', NULL, 0, 34, NULL);
INSERT INTO `products` (`id`, `product_name`, `slug`, `type_id`, `price`, `capacity`, `alcohol`, `origin`, `manufacturer_id`, `category_id`, `detail`, `create_at`, `update_at`, `is_delete`, `quantity`, `status`) VALUES ('VD/1603', 'Rượu vang đỏ Domaine Faiveley Mercurey Vieilles Vignes 2023', 'ruou-vang-do-domaine-faiveley-mercurey-vieilles-vignes-2023', 1, 1595000.00, '750ML', 0, 'Pháp', 8, 5, 'Domaine Faiveley và hành trình làm vang kéo dài 2 thế kỷ\r\nDomaine Faiveley là điền trang danh giá với hơn 200 năm lịch sử tại Bourgogne, Pháp\r\nĐược thành lập từ năm 1825 tại thị trấn Nuits-Saint-Georges – trái tim của tiểu vùng Côte de Nuits, Domaine Faiveley là một trong những điền trang danh tiếng bậc nhất của vùng\r\nBourgogne\r\n. Kể từ năm 2005, thế hệ thứ 7 của gia đình Faiveley – Erwan và Eve Faiveley đã nắm quyền quản lý thương hiệu, tiếp nối truyền thống làm vang đầy tâm huyết.\r\nVới hơn 120 hecta vườn nho, trải dài khắp các tiểu vùng Côte de Nuits, Côte de Beaune và Côte Chalonnaise,\r\nDomaine Faiveley\r\ntự hào là một trong những điền trang rượu vang lớn mạnh nhất tại Bourgogne, sở hữu 12 hecta vườn nho xếp hạng Grand Cru và 25 hecta vườn nho xếp hạng Premier Cru. Thương hiệu cũng nổi tiếng với những dòng\r\nrượu vang đỏ Pinot Noir\r\nvà\r\nrượu vang trắng Chardonnay\r\nchất lượng, được sản xuất từ nho canh tác theo hướng hữu cơ hoàn toàn từ năm 2022.\r\nMercurey – Tiểu vùng rượu vang danh giá\r\nTại Bourgogne, Mercurey là tiểu vùng danh giá đã sản sinh nên vô số dòng rượu vang hảo hạng. Tên gọi Mercurey bắt nguồn từ tên của vị thần Mercury trong thần thoại La Mã. Về vị trí, Mercurey là nơi nối liền 2 thị trấn Chalon-sur-Saône và Autun vào thời La Mã cổ đại. Tiểu vùng Mercurey cũng sở hữu lịch sử trồng nho và sản xuất rượu vang từ lâu đời.\r\nDomaine Faiveley đã tiến hành trồng và canh tác nho từ các vườn nho có độ tuổi từ 50 đến 60 năm tại Mercurey, thành công mang lại những dòng rượu vang đậm đà, được tín đồ vang Pháp thế giới đánh giá cao.\r\nVang đỏ pha trộn nho từ 20 vườn nho tại Bourgogne\r\nDomaine Faiveley đã chọn lọc những trái nho\r\nPinot Noir\r\nchất lượng nhất, đến từ 20 vườn nho khác nhau để tạo nên vang đỏ Domaine Faiveley Mercurey Vieilles Vignes 2023. Những cây nho có tuổi thọ trung bình là 30 năm, trồng trên thổ nhưỡng đất đá vôi đã kết tinh nên những dòng vang mang hương thơm nồng nàn, phản ánh chân thực linh hồn vùng đất Mercurey.\r\nMua sắm rượu vang Domaine Faiveley Bourgogne Pinot Noir 2023 tại Grand Cru – Modern Wine Bar\r\nVới danh mục rượu vang đa dạng, bao gồm hơn 1500 sản phẩm\r\nvang nhập khẩu\r\ntừ các nhà sản xuất và thương hiệu vang danh tiếng trên toàn thế giới,\r\nGrand Cru – Modern Wine Bar\r\ntự hào là đơn vị nhập khẩu và phân phối các sản phẩm rượu vang từ thương hiệu Domaine Faiveley chính hãng. Chúng tôi cam kết mang tới sản phẩm với chất lượng và mức giá hấp dẫn nhất thị trường, phù hợp để làm quà tặng trong những dịp đặc biệt lẫn thưởng thức hàng ngày.\r\nQuý khách hàng có nhu cầu mua sắm rượu vang Domaine Faiveley vui lòng liên hệ với chúng tôi qua Hotline 090 479 90 09 hoặc Fanpage Grand Cru – Modern Wine Bar để được tư vấn và đặt hàng các sản phẩm nhanh chóng nhất.', '2025-12-18 21:47:17', NULL, 0, 53, NULL);
INSERT INTO `products` (`id`, `product_name`, `slug`, `type_id`, `price`, `capacity`, `alcohol`, `origin`, `manufacturer_id`, `category_id`, `detail`, `create_at`, `update_at`, `is_delete`, `quantity`, `status`) VALUES ('VD/1607', 'Rượu vang đỏ Domaine Faiveley Nuits-Saint-Georges “Les Montroziers” 2022', 'ruou-vang-do-domaine-faiveley-nuits-saint-georges-les-montroziers-2022', 1, 3300000.00, '750ML', 13, 'Pháp', 8, 5, 'Domaine Faiveley – Viên ngọc quý từ Nuits-Saint-Georges\r\nDomaine Faiveley là điền trang vang Pháp với hơn 200 năm lịch sử tại Nuits-Saint-Georges\r\nDomaine Faiveley\r\nlà một trong những nhà sản xuất rượu vang danh tiếng nhất của vùng\r\nBourgogne\r\n, Pháp. Với lịch sử hình thành từ năm 1825, trải qua hơn 200 năm phát triển với 7 thế hệ gia đình làm vang đầy nhiệt huyết, Domaine Faiveley được giới chuyên gia và tín đồ yêu vang thế giới tôn vinh như viên ngọc quý từ Nuits-Saint-Georges.\r\nDomaine Faiveley tự hào sở hữu hơn 120 hecta vườn nho, trải dài từ Côte de Nuits, Côte de Beaune đến Côte Chalonnaise, trong đó có nhiều vườn nho được xếp hạng Grand Cru và Premier Cru. Thương hiệu cũng nổi tiếng với triết lý làm vang kết hợp hài hòa giữa truyền thống lâu đời và công nghệ hiện đại, thành công mang lại những dòng vang mang hương vị tinh tế, cấu trúc cân bằng và tiềm năng lưu giữ dài lâu.\r\nDòng vang đỏ mang ý nghĩa đặc biệt\r\nDomaine Faiveley Nuits-Saint-Georges Les Montroziers\r\nlà dòng\r\nvang đỏ\r\nđược Domaine Faiveley sản xuất nhằm tri ân chính khách Maurice Colrat de Montrozier – người có tầm ảnh hưởng nhất định tới Domaine Faiveley trong giai đoạn đầu thế kỷ 20. Chai vang này cũng là minh chứng cho sự kết hợp giữa yếu tố truyền thống và hiện đại trong phong cách sản xuất rượu vang của Domaine Faiveley.\r\nRượu vang Domaine Faiveley Nuits-Saint-Georges Les Montroziers 2022 được sản xuất từ thành phần 100% nho đỏ Pinot Noir, canh tác trên 4 hecta vườn nho, trải dài từ Bắc xuống Nam tại Nuits-Saint-Georges. Vườn nho Argillats với thổ nhưỡng giàu sỏi đã mang đến cho rượu những nốt hương thơm tinh tế, trong khi vườn Lavières với thổ nhưỡng giàu đất sét vôi, bùn và đá vôi cứng mang đến sự cô đọng và chiều sâu cho rượu.\r\nTrọn vị vang đỏ cùng ly Riedel Superleggero Burgundy Grand Cru Red Stem\r\nLy Riedel Superleggero Burgundy Grand Cru Red Stem là dáng ly pha lê thổi thủ công, được thiết kế chuyên biệt cho những dòng vang đỏ Bourgogne Pinot Noir như Domaine Faiveley Nuits-Saint-Georges Les Montroziers 2022. Hình dáng bầu ly lớn, miệng ly loe rộng giúp rượu vang trong ly được tiếp xúc tối đa với không khí, từ đó giải phóng hương thơm và làm mềm vị chát trong rượu. Với điểm nhấn nằm ở chân ly màu đỏ, thiết kế này không chỉ tối ưu trải nghiệm thưởng thức mà còn tôn lên vẻ sang trọng của mọi bàn tiệc nó hiện diện.\r\nLy Riedel Superleggero Burgundy Grand Cru Red Stem\r\nMua sắm rượu vang Domaine Faiveley Nuits-Saint-Georges Les Montroziers 2022 tại Grand Cru – Modern Wine Bar\r\nVới danh mục rượu vang đa dạng, bao gồm hơn 1500 sản phẩm\r\nvang nhập khẩu\r\ntừ các nhà sản xuất và thương hiệu vang danh tiếng trên toàn thế giới,\r\nGrand Cru – Modern Wine Bar\r\ntự hào là đơn vị nhập khẩu và phân phối các sản phẩm rượu vang từ thương hiệu Domaine Faiveley chính hãng. Chúng tôi cam kết mang tới sản phẩm với chất lượng và mức giá hấp dẫn nhất thị trường, phù hợp để làm quà tặng trong những dịp đặc biệt lẫn thưởng thức hàng ngày.\r\nQuý khách hàng có nhu cầu mua sắm rượu vang Domaine Faiveley vui lòng liên hệ với chúng tôi qua Hotline 090 479 90 09 hoặc Fanpage Grand Cru – Modern Wine Bar để được tư vấn và đặt hàng các sản phẩm nhanh chóng nhất.', '2025-12-18 21:47:17', NULL, 0, 15, NULL);
INSERT INTO `products` (`id`, `product_name`, `slug`, `type_id`, `price`, `capacity`, `alcohol`, `origin`, `manufacturer_id`, `category_id`, `detail`, `create_at`, `update_at`, `is_delete`, `quantity`, `status`) VALUES ('VD/0918-19', 'Rượu Vang Đỏ Château Dauzac 2019', 'ruou-vang-do-chateau-dauzac-2019', 1, 3080000.00, '750ML', 14, 'Pháp', 9, 1, 'Château Dauzac\r\nlà điền trang xếp hạng Fifth Growth danh tiếng của vùng rượu Margaux, Pháp. Điền trang do Jean Cousseau thành lập từ năm 1622 và đã trải qua nhiều lần thay đổi người sở hữu. Château Dauzac hiện thuộc quyền sở hữu của Christian Roulleau và gia đình Roulleau, sản xuất nên những dòng rượu vang đỏ đậm đà, phức hợp in đậm dấu ấn thổ nhưỡng tuyệt vời của vùng rượu Margaux.\r\nGiống như các điền trang rượu vang hàng đầu Margaux,\r\nChâteau Dauzac\r\ntập trung phát triển các giống nho Cabernet Sauvignon, Merlot và Petit Verdot. Nhà sản xuất sở hữu vườn nho liền kề rộng 49 hecta, nằm cách cửa sông Gironde 350 mét. Vị trí địa lý thuận lợi đã mang đến cho Château Dauzac thổ nhưỡng đất sét pha sỏi, bao phủ bởi chất đất phù sa cổ đại màu mỡ được xếp vào hạng đặc biệt nhất tại Margaux.\r\nĐiền trang theo đuổi phương thức làm vang truyền thống, đồng thời áp dụng nhiều đổi mới để nâng cao chất lượng vang, thành công mang đến những dòng vang chất lượng, được giới chuyên môn và tín đồ vang Pháp toàn cầu đánh giá cao.', '2025-12-18 21:47:17', NULL, 0, 89, NULL);
INSERT INTO `products` (`id`, `product_name`, `slug`, `type_id`, `price`, `capacity`, `alcohol`, `origin`, `manufacturer_id`, `category_id`, `detail`, `create_at`, `update_at`, `is_delete`, `quantity`, `status`) VALUES ('VD/1475-12-9L', 'Rượu vang đỏ Rubinelli Vajol Valpolicella Ripasso Classico Superiore 2012', 'ruou-vang-do-rubinelli-vajol-valpolicella-ripasso-classico-superiore-2012', 1, 22385000.00, '9L', 0, 'Ý', 10, 7, '', '2025-12-18 21:47:17', NULL, 0, 98, NULL);
INSERT INTO `products` (`id`, `product_name`, `slug`, `type_id`, `price`, `capacity`, `alcohol`, `origin`, `manufacturer_id`, `category_id`, `detail`, `create_at`, `update_at`, `is_delete`, `quantity`, `status`) VALUES ('VD/1475-18-6L', 'Rượu vang đỏ Rubinelli Vajol Valpolicella Ripasso Classico Superiore 2018 6L', 'ruou-vang-do-rubinelli-vajol-valpolicella-ripasso-classico-superiore-2018-6l', 1, 14278000.00, '6L', 0, 'Ý', 10, 7, 'Dòng rượu vang Valpolicella cổ điển quyến rũ\r\nMỗi mai chai rượu vang được\r\nRubinelli Vajol\r\nsản xuất đều mang phần hồn của vùng đất Valpolicella. Đối với dòng\r\nrượu vang Valpolicella Ripasso Classico Superiore\r\n, quả nho được thu hoạch ở độ chín tối ưu với độ đường thấp, đem lại hương vị trái quả chín thơm ngon, bộc lộ những cá tính độc đáo của nho được canh tác trên thổ nhưỡng đất sét và đá vôi. Ngoài những giống nho truyền thống của khu vực, nhà sản xuất được phép sử dụng 10% giống nho quốc tế cho dòng rượu Valpolicella Ripasso Classico Superiore. Tuy nhiên, Rubinelli Vajol vẫn sử dụng các giống nho địa phương với 5% Molinara và 5% Omeleta để giữ nguyên hương vị truyền thống của khu vực Valpolicella.\r\nRubinelli Vajol Valpolicella Ripasso Classico Superiore 2018 là một dòng rượu Valpolicella cổ điển quyến rũ với hương vị thơm ngon, được sản xuất bằng phương pháp ri-passo, lên men lần thứ 2 với bã nho của dòng rượu Amarone để tăng thêm chất vị đậm đà, đem lại hương vị, cấu trúc hài hòa hơn.', '2025-12-18 21:47:17', NULL, 0, 23, NULL);
INSERT INTO `products` (`id`, `product_name`, `slug`, `type_id`, `price`, `capacity`, `alcohol`, `origin`, `manufacturer_id`, `category_id`, `detail`, `create_at`, `update_at`, `is_delete`, `quantity`, `status`) VALUES ('VD/0834-13-1.5L', 'Rượu Vang Đỏ Sandrone Barolo Le Vigne – 1.5L 2013', 'ruou-vang-do-sandrone-barolo-le-vigne-15l-2013', 1, 14828000.00, '1.5L', 14.5, 'Ý', 11, 8, '', '2025-12-18 21:47:17', NULL, 0, 18, NULL);
INSERT INTO `products` (`id`, `product_name`, `slug`, `type_id`, `price`, `capacity`, `alcohol`, `origin`, `manufacturer_id`, `category_id`, `detail`, `create_at`, `update_at`, `is_delete`, `quantity`, `status`) VALUES ('VD/0834-14-1.5L', 'Rượu Vang Đỏ Sandrone Barolo Le Vigne – 1.5L 2014', 'ruou-vang-do-sandrone-barolo-le-vigne-15l-2014', 1, 13486000.00, '1.5L', 14.5, 'Ý', 11, 8, '', '2025-12-18 21:47:17', NULL, 0, 21, NULL);
INSERT INTO `products` (`id`, `product_name`, `slug`, `type_id`, `price`, `capacity`, `alcohol`, `origin`, `manufacturer_id`, `category_id`, `detail`, `create_at`, `update_at`, `is_delete`, `quantity`, `status`) VALUES ('VD/1290', 'Rượu Vang Đỏ Méo-Camuzet Chambolle Musigny Premier Cru Les Charmes 2020', 'ruou-vang-do-meo-camuzet-chambolle-musigny-premier-cru-les-charmes-2020', 1, 9658000.00, '750ML', 13, 'Pháp', 12, 5, 'Rượu vang đỏ từ thửa ruộng Chambolle-Musigny Premier Cru\r\nRượu vang dán nhãn\r\nChambolle-Musigny Premier Cru\r\nđược sản xuất độc quyền hoàn toàn từ nho Pinot Noir, được thu hoạch từ 24 địa điểm trồng nho hoặc tiểu vùng khí hậu hàng đầu trong phân loại chính thức của làng.\r\nCác vườn nho\r\nChambolle-Musigny Premier Cru\r\nhàng đầu nằm trên các loại đất mịn, thoát nước tốt ở giữa sườn dốc của vách đá Côte d’Or, tạo thành một dải chạy dọc từ bắc xuống nam ngay dưới làng.\r\nCác quy tắc sản xuất\r\nrượu vang Chambolle-Musigny Premier Cru\r\ncũng nghiêm ngặt hơn so với quy tắc đóng chai cấp làng, mang đến phong vị cổ điển mạnh mẽ nhưng tinh tế, nổi bật bằng sự cân bằng giữa sự phong phú và sang trọng.', '2025-12-18 21:47:17', NULL, 0, 52, NULL);
INSERT INTO `products` (`id`, `product_name`, `slug`, `type_id`, `price`, `capacity`, `alcohol`, `origin`, `manufacturer_id`, `category_id`, `detail`, `create_at`, `update_at`, `is_delete`, `quantity`, `status`) VALUES ('VD/0883-09-3L', 'Rượu Vang Đỏ Muga Prado Enea Gran Reserva 2009 3 Lít', 'ruou-vang-do-muga-prado-enea-gran-reserva-2009-3-lit', 1, 9460000.00, '3L', 14.5, 'Tây Ban Nha', 13, 9, 'Bodegas Muga – nhà sản xuất rượu vang biểu tượng Tây Ban Nha\r\nBodegas Muga\r\nlà một trong những biểu tượng trong lĩnh vực sản xuất rượu vang Tây Ban Nha. Điền trang được gia đình Muga sáng lập vào năm 1932 tại vùng Rioja. Với hơn 250 ha vườn nho tọa lạc xung quanh thị trấn Haro, nhà sản xuất Muga nổi danh với sự tận tụy và chất lượng cao trong sản xuất rượu vang Reserva truyền thống.\r\nGia đình Muga tập trung vào sử dụng trái cây từ vườn nho Baltracones truyền thống, với đất phù sa và đất phấn phù hợp cho giống nho Tempranillo và Garnacha. Danh mục rượu vang Muga thể hiện đẳng cấp với sản phẩm đỉnh cao là\r\nPrado Enea Gran Reserva\r\n, một sự kết hợp tài tình của các giống nho Tempranillo, Grenache, Mazuelo và Graciano. Quá trình ủ lâu dài trong thùng gỗ sồi lớn tạo nên phong cách độc đáo cho các sản phẩm của Muga.', '2025-12-18 21:47:17', NULL, 0, 97, NULL);
INSERT INTO `products` (`id`, `product_name`, `slug`, `type_id`, `price`, `capacity`, `alcohol`, `origin`, `manufacturer_id`, `category_id`, `detail`, `create_at`, `update_at`, `is_delete`, `quantity`, `status`) VALUES ('VD/0883-14', 'Rượu Vang Đỏ Muga Prado Enea Gran Reserva 2014', 'ruou-vang-do-muga-prado-enea-gran-reserva-2014', 1, 2783000.00, '750ML', 14.5, 'Tây Ban Nha', 13, 9, 'Niên vụ 2014 tại điền trang Muga\r\nNiên vụ 2014 tại Tây Ban Nha ảnh hưởng bởi một số yếu tố thiên nhiên và thời tiết đặc biệt, tạo ra những thách thức và cơ hội đối với các nhà sản xuất rượu vang nơi này.\r\nMùa xuân năm 2014 bắt đầu khá mát mẻ và mưa tương đối nhiều, khiến cho sự phát triển của cây nho được ghi nhận chậm hơn mọi năm. Tuy nhiên, điều này đã giúp cây nho tránh được nguy cơ đóng bông sớm, giúp cho quả nho trở nên tươi sáng và bền vững hơn khi trải qua một mùa mưa lớn vào mùa hè.\r\nMùa hè của năm 2014 tại Tây Ban Nha được mô tả là nắng đặc trưng kiểu nhiệt đới, điều này đã giúp cây nho phát triển nhanh chóng và tạo ra những quả nho chín đẹp. Sự kết hợp giữa mưa mùa xuân và nắng mùa hè đã làm cho các quả nho có chất lượng tốt, với hương vị phong phú và vị chua cân đối. Một số chai rượu vang nổi bật từ niên vụ này có thể được lưu trữ và thưởng thức trong nhiều năm, còn một số khác thì phù hợp để uống ngay.', '2025-12-18 21:47:17', NULL, 0, 26, NULL);
INSERT INTO `products` (`id`, `product_name`, `slug`, `type_id`, `price`, `capacity`, `alcohol`, `origin`, `manufacturer_id`, `category_id`, `detail`, `create_at`, `update_at`, `is_delete`, `quantity`, `status`) VALUES ('VD/0817', 'Rượu Vang Đỏ Nipozzano Montesodi Chianti Rufina 2015', 'ruou-vang-do-nipozzano-montesodi-chianti-rufina-2015', 1, 1650000.00, '750ML', 14, 'Ý', 14, 10, '', '2025-12-18 21:47:17', NULL, 0, 38, NULL);
INSERT INTO `products` (`id`, `product_name`, `slug`, `type_id`, `price`, `capacity`, `alcohol`, `origin`, `manufacturer_id`, `category_id`, `detail`, `create_at`, `update_at`, `is_delete`, `quantity`, `status`) VALUES ('VT/0053', 'Rượu Sâm Panh Champagne Charles Heidsieck Brut Réserve', 'ruou-sam-panh-champagne-charles-heidsieck-brut-reserve', 2, 2526000.00, '750ML', 12, 'Pháp', 15, 11, 'Charles Heidsieck – Nhà sản xuất champagne danh tiếng\r\nCharles Heidsieck\r\nlà một trong những nhà sản xuất champagne danh tiếng hàng đầu thế giới. Điền trang hoạt động vào năm 1851 khi nhà sáng lập\r\nCharlie Heidsieck\r\n– bắt đầu tự mình kinh doanh dưới cái tên ban đầu là “Champagne Charlie” . Thay vì đầu tư vào vườn nho,\r\nHeidsieck\r\nđầu tư vào hầm chứa phấn dưới lòng đất ở trung tâm Reims.\r\nNăm 1852,\r\nCharles Heidsieck\r\ntấn công sang thị trường Mỹ. Ông đã đạt được thành công lớn ở đó và được coi là một đại sứ, không chỉ cho những dòng champagne cao cấp nói riêng mà còn cho cả văn hóa và nghệ thuật rượu vang nước Pháp nói chung.\r\nNgày nay,\r\nChampagne Charles Heidsieck\r\nlà biểu tượng cho dòng rượu vang sủi cao cấp. Điền trang sản xuất cả dòng champagne brut cổ điển và champagne rosé không cổ điển. Cả hai dòng đều có thời gian ngâm ủ 3 năm, dài hơn khoảng 20 tháng so với quy định sản xuất đối với rượu champagne không cổ điển.', '2025-12-18 21:47:17', NULL, 0, 14, NULL);
