INSERT INTO `products` (`id`, `product_name`, `slug`, `type_id`, `price`, `capacity`, `alcohol`, `origin`, `manufacturer_id`, `category_id`, `detail`, `create_at`, `update_at`, `is_delete`, `quantity`, `status`) VALUES ('VD/0163', 'Rượu Sâm Panh Champagne Charles Heidsieck Rosé Réserve', 'ruou-sam-panh-champagne-charles-heidsieck-rose-reserve', 2, 3630000.00, '750ML', 12, 'Pháp', 15, 11, 'Charles Heidsieck – nhà sản xuất champagne danh tiếng\r\nNgay từ những ngày thành lập năm 1851, rượu vang của\r\nCharles Heidsieck\r\nđã tạo được ấn tượng và nét hấp dẫn trong các cung đình hoàng gia Châu Âu. Ngày nay, champagne của\r\nCharles Heidsieck\r\nđược các chuyên gia rượu vang chuyên nghiệp trên toàn thế giới trao tặng những giải thưởng cao nhất.\r\nSố lượng huy chương và danh hiệu mà\r\nCharles Heidsieck\r\nthường xuyên đạt được thật phi thường. Đội ngũ sản xuất rượu vang đã 9 lần được trao cúp “Nhà sản xuất rượu của năm” tại UK International Wine Challenge (Cuộc thi Thử thách Rượu vang Quốc tế Vương quốc Anh)\r\nRégis Camus gia nhập\r\nCharles Heidsieck\r\nvào năm 1994 và là nhà sản xuất rượu đứng đầu của điền trang từ năm 2002. Chuyên gia tỉ mỉ và đầy đam mê này thích theo dõi mọi thứ: tình trạng của các vườn nho, việc lựa chọn nho, quá trình ép và quá trình lên men của chúng, từng thứ một, trong từng thùng riêng lẻ. Sứ mệnh của ông là duy trì phong cách\r\nCharles Heidsieck\r\nvà phản ánh sự phong phú của vùng đất Champagne.', '2025-12-18 21:47:17', NULL, 0, 98, NULL);
