INSERT INTO `products` (`id`, `product_name`, `slug`, `type_id`, `price`, `capacity`, `alcohol`, `origin`, `manufacturer_id`, `category_id`, `detail`, `create_at`, `update_at`, `is_delete`, `quantity`, `status`) VALUES ('VT/0324', 'Rượu Vang Sủi Gemma Di Luna Prosecco Extra Dry', 'ruou-vang-sui-gemma-di-luna-prosecco-extra-dry', 9, 528000.00, '750ML', 10.5, 'Ý', 30, 20, 'Gemma di Luna – biểu tượng xanh ngọc của cuộc sống tươi đẹp “la bella vita”\r\nGemma di Luna\r\nnổi tiếng với các dòng vang Ý ngọt mát, trẻ trung, tươi mới, được làm từ nguồn nguyên liệu nho hảo hạng, lựa chọn tỉ mỉ theo tiêu chuẩn chất lượng cao. Từng giọt vang bung toả hương thơm thanh mát và đầy lôi cuốn.\r\nBộ sưu tập Luxury Collection được tuyển chọn từ những chai vang xuất xắc nhất. Chỉn chu từ vẻ bề ngoài đến chất lượng, BST đã biến những khoảnh khắc thường ngày trở nên vô cùng đáng nhớ, thể hiện trọn vẹn phong cách sống đầy nghệ thuật và chất thơ của con người Ý.\r\nProsecco – dòng vang sủi Ý nổi tiếng toàn cầu\r\nProsecco\r\nlà một dòng\r\nrượu vang sủi\r\nđược phân hạng\r\nDOC\r\nhoặc\r\nDOCG\r\nnổi tiếng ở vùng Đông Bắc nước Ý, được sản xuất trên một khu vực rộng lớn trải dài tại chín tỉnh tại vùng\r\nVeneto\r\nvà\r\nFriuli-Venezia Giulia\r\n. Prosecco là 1 tên gọi khác cho giống nho dùng để sản xuất dòng vang sủi này, được biết đến với tên gọi chính thức là Glera.\r\nPhân hạng\r\nDOC Prosecco\r\nđược công nhận từ năm 2009, quy định rượu vang sủi cần có tổi thiểu 85% giống nho Glera và tối đa 15% còn lại cho các giống nho Chardonnay, Pinot Bianco, Pinot Grigio, Verdiso, Bianchetta Trevigiana, Perera và Glera Lunga.\r\nDOC Prosecco có 3 phong cách rượu: rượu không sủi Prosecco hiếm khi gặp, rượu sủi nhẹ Frizzante và rượu nhiều sủi Spumante.\r\nTrong tiểu vùng DOC Prosecco rộng lớn, DOCG Prosecco Superiore được ghi nhận cho những thổ nhưỡng đặc biệt chất lượng tốt, như những khu vực đồi của Conegliano-Valdobbiadene và Colli Asolani.\r\nPhương pháp sản xuất vang sủi tại Prosecco được gọi là Charmat method để phân biệt với phương pháp truyền thống (phương pháp của vùng Champagne). Hương vị rượu vang sủi nhẹ nhàng, tươi mát hương táo xanh, đào trắng, thơm ngon dễ uống và giá rất tốt.', '2025-12-18 21:47:17', NULL, 0, 61, NULL);
INSERT INTO `products` (`id`, `product_name`, `slug`, `type_id`, `price`, `capacity`, `alcohol`, `origin`, `manufacturer_id`, `category_id`, `detail`, `create_at`, `update_at`, `is_delete`, `quantity`, `status`) VALUES ('VT/0346-19', 'Rượu Vang Ngọt Château Roumieu 2019', 'ruou-vang-ngot-chateau-roumieu-2019', 10, 1185800.00, '750ML', 0, 'Pháp', 31, 1, '', '2025-12-18 21:47:17', NULL, 0, 71, NULL);
INSERT INTO `products` (`id`, `product_name`, `slug`, `type_id`, `price`, `capacity`, `alcohol`, `origin`, `manufacturer_id`, `category_id`, `detail`, `create_at`, `update_at`, `is_delete`, `quantity`, `status`) VALUES ('VD/1306', 'Rượu Vang Hồng Tenuta Ammiraglia Alìe', 'ruou-vang-hong-tenuta-ammiraglia-alie', 4, 726000.00, '750ML', 12, 'Ý', 32, 7, 'Tổng quan về nhà sản xuất Marchesi Frescobaldi\r\nMarchesi Frescobaldi\r\nlà một trong những nhà máy rượu vang lâu đời nhất tại Ý với lịch sử làm rượu từ những năm 1300. Với giới chuyên môn và tín đồ\r\nrượu vang Ý\r\n, Frescobaldi là nhà làm vang mang tính biểu tượng, có tầm ảnh hưởng quan trọng nhất ở Ý với nhiều dòng\r\nrượu vang hảo hạng\r\n, minh chứng qua loạt đánh giá của giới chuyên gia và giải thưởng từ những cuộc thi rượu vang uy tín.\r\nTenuta Ammiraglia – Điền trang rượu vang danh tiếng của Marchesi Frescobaldi\r\nMen theo những ngọn đồi từ Chianti đến Siena, từ Montepulciano và Montalcino đến cánh rừng Apennines rộng lớn,\r\nTenuta Ammiraglia\r\nvới những vườn nho nằm ở độ cao 700m so với mực nước biển là 1 trong số 8 điền trang làm rượu danh giá nhất của thương hiệu Frescobaldi. Địa hình đặc biệt, kết hợp với ảnh hưởng của mặt trời và gió biển Địa Trung Hải mang đến cho Tenuta Ammiraglia tiềm năng đặc biệt, có khả năng tạo nên những dòng rượu vang trắng, rượu vang hồng tươi mát, nổi bật với hương khoáng chất và trái cây sống động.\r\nQuy trình sản xuất rượu vang hồng Tenuta Ammiraglia Alìe 2021\r\nThành công của\r\nrượu vang Tenuta Ammiraglia Alìe 2021\r\nđến từ sự kết hợp giữa các yếu tố thổ nhưỡng, kỹ thuật chăm sóc và quy trình sản xuất công phu của đội ngũ làm vang tại Tenuta Ammiraglia. Sau khi thu hoạch, những trái nho Vermentino và Syrah được chuyển tới nhà máy rượu và ép nhẹ bằng máy trong khoảng 12 giờ. Quy trình ép chậm này đã giúp nhà sản xuất thành công mang tới hương vị\r\nvang hồng\r\nđầy quyến rũ. Rượu được lên men trong các thùng thép không gỉ ở nhiệt độ được kiểm soát ở mức thấp hơn 19° C, ủ thêm trên bã mịn thêm vài tháng trước khi sẵn sàng bày bán ra thị trường.\r\nQuà tặng rượu vang hồng Tenuta Ammiraglia Alìe 2021\r\nNhững chai vang hồng với hương vị thơm ngon, sắc hồng ngọt ngào và giá cả phải chăng như\r\nTenuta Ammiraglia Alìe 2021\r\nchính là lựa chọn hoàn hảo cho\r\nquà tặng\r\nnhân dịp đặc biệt như 8/3, 20/10 đến ngày sinh nhật của phái Đẹp. Quý khách hàng quan tâm đến các sản phẩm rượu vang hồng nhập khẩu và có nhu cầu mua\r\nrượu vang hồng Tenuta Ammiraglia Alìe 2021\r\nlàm quà tặng có thể truy cập website\r\nGrandCru.vn\r\nhoặc liên hệ hotline 090 479 9009 để nhận tư vấn.', '2025-12-18 21:47:17', NULL, 0, 72, NULL);
