INSERT INTO `products` (`id`, `product_name`, `slug`, `type_id`, `price`, `capacity`, `alcohol`, `origin`, `manufacturer_id`, `category_id`, `detail`, `create_at`, `update_at`, `is_delete`, `quantity`, `status`) VALUES ('VD/0425', 'Rượu Vang Đỏ Insoglio, 3L 2015', 'ruou-vang-do-insoglio-3l-2015', 1, 4356000.00, '3L', 14, 'Ý', 45, 7, 'Chất vị vang Ý hảo hạng từ điền trang danh tiếng\r\nTenuta di Biserno\r\nnhà sản xuất rượu vang danh tiếng nằm ở biên giới Bolgheri,\r\nTuscany\r\n, nước Ý. Được thành lập vào năm 1995, điền trang Tenuta di Birserno được thành lập bởi Lodovico Antinori, nhà làm vang sở hữu điền trang Ornellaia nổi tiếng. Ban đầu, vùng đất này thuộc quyền sở hữu của Ornellaia, tuy nhiên Antinori nhận thấy rằng vùng thổ nhưỡng này quá khác biệt với địa hình nhiều đồi núi với chất đất phù sa hòa trộn cùng đất đá vôi giàu khoáng. Điểm đặc biệt này có tiềm năng tạo lên một phong cách rượu vang hoàn toàn mới nên đã quyết định phát triển một dự án đặc biệt cho vùng lãnh thổ này. Cho đến hiện tại, Tenuta di Biserno đã sở hữu cho mình một bộ sưu tập lớn các dòng\r\nrượu vang Super Tuscan\r\nvới phong cách của riêng mình với phân hạng là IGT Toscana –\r\nrượu vang chất lượng hảo hạng\r\ntừ bàn tay của những con người vùng Tuscan.\r\nĐiền trang dành riêng cho dòng\r\nvang Tenuta di Biserno\r\nnằm trên lãnh thổ vùng Alta Maremma gần bờ biển, được làm mát bởi gió biển Địa Trung Hải. Thổ nhưỡng nơi đây chủ yếu là phù sa, được tạo thành từ đá vôi và canxi cacbonat, một điều kiện tự nhiên tuyệt vời cho các giống nho\r\nCabernet Franc\r\nvà\r\nCabernet Sauvignon\r\nsinh trưởng. Hai giống nho này sớm được trồng từ năm 2003 và sau đó Merlot và Petit Verdot cũng được đưa vào trồng ở điền trang này.', '2025-12-18 21:47:17', NULL, 0, 41, NULL);
