INSERT INTO `products` (`id`, `product_name`, `slug`, `type_id`, `price`, `capacity`, `alcohol`, `origin`, `manufacturer_id`, `category_id`, `detail`, `create_at`, `update_at`, `is_delete`, `quantity`, `status`) VALUES ('VD/1293-21', 'Rượu vang đỏ Méo-Camuzet Clos de Vougeot Grand Cru 2021', 'ruou-vang-do-meo-camuzet-clos-de-vougeot-grand-cru-2021', 1, 13420000.00, '750ML', 0, 'Pháp', 12, 5, '', '2025-12-18 21:47:17', NULL, 0, 29, NULL);
INSERT INTO `products` (`id`, `product_name`, `slug`, `type_id`, `price`, `capacity`, `alcohol`, `origin`, `manufacturer_id`, `category_id`, `detail`, `create_at`, `update_at`, `is_delete`, `quantity`, `status`) VALUES ('VT/0420-375ML', 'Rượu Sâm Panh Champagne Henriot Brut Souverain 375ml', 'ruou-sam-panh-champagne-henriot-brut-souverain-375ml', 2, 913000.00, '375ML', 12, 'Pháp', 47, 11, 'Champagne Henriot – Đỉnh cao nghệ thuật pha trộn\r\nTừ khi thành lập vào năm 1808, 8 thế hệ của gia đình Henriot đã nỗ lực không ngơi nghỉ để gìn giữ và phát huy tinh thần của nhà sáng lập Apolline Henriot – đưa hương vị thổ nhưỡng tỏa sáng trong từng dòng Champagne. Ngày nay,\r\nChampagne Henriot\r\nđã khẳng định được vị thế trên thị trường và vinh dự thuộc TOP các thương hiệu Champagne được ngưỡng mộ nhất toàn cầu.\r\nChampagne Henriot\r\nsở hữu 6 thửa ruộng Grand Cru đắt giá ở Montagne de Reims và Côte des Blancs. Ngoài ra, họ còn thu mua thêm các mẻ nho Grand Cru, Premier Cru chất lượng cao tại các thửa ruộng xung quanh khu vực Épernay nổi tiếng để làm rượu. Phong cách Champagne Henriot được định hình bởi sự am hiểu sâu sắc về thổ nhưỡng, khí hậu và nghệ thuật pha trộn bậc thầy của các thế hệ Henriot.', '2025-12-18 21:47:17', NULL, 0, 49, NULL);
INSERT INTO `products` (`id`, `product_name`, `slug`, `type_id`, `price`, `capacity`, `alcohol`, `origin`, `manufacturer_id`, `category_id`, `detail`, `create_at`, `update_at`, `is_delete`, `quantity`, `status`) VALUES ('VT/0475-169', 'Rượu Sâm Panh Champagne Krug Grande Cuvée 169ème Édition Brut', 'ruou-sam-panh-champagne-krug-grande-cuvee-169eme-edition-brut', 2, 16940000.00, '750ML', 12.5, 'Pháp', 48, 11, 'Krug – Thương hiệu champagne danh giá với 6 thế hệ nối tiếp nhau\r\nChampagne Krug\r\nđược thành lập vào năm 1843 bởi Joseph Krug – Một người có tầm nhìn xa trông rộng, ước mơ tạo ra dòng champagne ngon nhất có thể mỗi năm, bất chấp sự thay đổi của khí hậu. Joseph Krug đã thực hiện được ước mơ của mình bằng cách chăm sóc tỉ mỉ từng vườn nho, tôn trọng cá tính của từng mảnh đất, từng dòng rượu và xây dựng một hệ thống lưu trữ rộng lớn gồm các loại rượu vang dự trữ từ nhiều niên vụ khác nhau. 6 thế hệ gia đình Krug đã theo đuổi triết lý của người sáng lập, cho ra đời những dòng champagne hảo hạng, được yêu thích trên khắp thế giới.\r\nHàng năm, đội ngũ\r\nChampagne Krug\r\ntái hiện giấc mơ của Joseph Krug bằng Phiên bản mới của\r\nKrug Grande Cuvée\r\n. Nguồn cảm hứng luôn xuyên suốt nhưng sự sáng tạo luôn hoàn toàn độc đáo và khác biệt trong mỗi niên vụ cụ thể.', '2025-12-18 21:47:17', NULL, 0, 60, NULL);
INSERT INTO `products` (`id`, `product_name`, `slug`, `type_id`, `price`, `capacity`, `alcohol`, `origin`, `manufacturer_id`, `category_id`, `detail`, `create_at`, `update_at`, `is_delete`, `quantity`, `status`) VALUES ('VT/0276', 'Rượu Sâm Panh Champagne Piper-Heidsieck Brut', 'ruou-sam-panh-champagne-piper-heidsieck-brut', 2, 2526000.00, '750ML', 12, 'Pháp', 49, 11, 'Nhà sản xuất Champagne Piper-Heidsieck\r\nChampagne Piper-Heidsieck\r\nsở hữu một lịch sử làm vang lâu đời và lừng lẫy tại vùng rượu Champagne, Pháp. Nhà sáng lập thương hiệu, Florens-Louis Heidsieck, là một doanh nhân người Đức đã chuyển đến Pháp vào cuối những năm 1700.\r\nNăm 1785, Florens thành lập công ty rượu vang Heidsieck & Co sau thời gian ngắn kinh doanh rượu thành công. Năm 1839, đam mê nghề trồng nho và sản xuất rượu vang một lần nữa trở thành động lực, thúc đẩy Florens-Louis Heidsieck thành lập thương hiệu danh tiếng\r\nChampagne Piper-Heidsieck\r\n.\r\nVới Florens-Louis Heidsieck, chìa khoá thành công đến từ tỉ lệ pha trộn hoàn hảo giữa thành phần các giống nho làm rượu. Đó cũng là triết lý sản xuất được các thế hệ gia đình Heidsieck gìn giữ và theo đuổi hàng trăm năm nay.\r\nCùng với\r\nCharles Heidsieck\r\n,\r\nPiper-Heidsieck\r\nhiện là một trong những nhà làm\r\nChampagne\r\nphổ biến và được săn đón nhiều nhất trên thế giới. Các dòng\r\nChampagne Piper-Heidsieck\r\ncũng xuất  hiện và được phục vụ trong nhiều sự kiện đặc biệt, bao gồm lễ khai trương Tháp Eiffel năm 1889, lễ đăng quang của Nữ hoàng Elizabeth II năm 1953 và đám cưới của Thái tử Charles và Công nương Diana Spencer năm 1981…, như những minh chứng cho sức hút và chất lượng của thuơng hiệu Champagne được ngưỡng mộ nhất thế giới.', '2025-12-18 21:47:17', NULL, 0, 50, NULL);
INSERT INTO `products` (`id`, `product_name`, `slug`, `type_id`, `price`, `capacity`, `alcohol`, `origin`, `manufacturer_id`, `category_id`, `detail`, `create_at`, `update_at`, `is_delete`, `quantity`, `status`) VALUES ('VT/0277-1.5L', 'Rượu Sâm Panh Champagne Piper-Heidsieck Brut 1.5L', 'ruou-sam-panh-champagne-piper-heidsieck-brut-15l', 2, 4422000.00, '1.5L', 12, 'Pháp', 49, 11, 'Triết lý sản xuất của Champagne của thương hiệu Piper-Heidsieck\r\nThành công trên toàn thế giới của\r\nPiper-Heidsieck\r\nđến từ niềm đam mê và chuyên môn của đội ngũ sản xuất trên vườn nho và trong hầm rượu.\r\nPiper-Heidsieck\r\ncam kết bảo vệ thổ nhưỡng của vườn nho thông qua nghề trồng nho bền vững, thể hiện qua chứng nhận kép gồm chứng nhận Viticulture Durable en Champagne và chứng nhận Haute Valeur Environnementale Fruit.\r\nTại các vườn nho nằm ở Montagne de Reims, Vallée de la Marne, Cote des Blancs và Cote des Bar, đội ngũ thợ trồng nho tại\r\nPiper-Heidsieck\r\ncam kết thực hiện các biện pháp thân thiện với môi trường, bao gồm việc giảm thiểu sử dụng các hoá chất, song song với nỗ lực cải thiện đa dạng sinh học, áp dụng nông lực hạn canh, quản lý năng lượng và chất thải.', '2025-12-18 21:47:17', NULL, 0, 69, NULL);
INSERT INTO `products` (`id`, `product_name`, `slug`, `type_id`, `price`, `capacity`, `alcohol`, `origin`, `manufacturer_id`, `category_id`, `detail`, `create_at`, `update_at`, `is_delete`, `quantity`, `status`) VALUES ('VT/0277', 'Rượu Sâm Panh Champagne Piper-Heidsieck Brut 6L', 'ruou-sam-panh-champagne-piper-heidsieck-brut-6l', 2, 32450000.00, '6L', 12, 'Pháp', 49, 11, 'Thương hiệu Champagne Piper-Heidsieck\r\nCâu chuyện về\r\nPiper-Heidsieck\r\nbắt đầu vào năm 1785 khi Florens-Louis Heidsieck thành lập hãng rượu Heidsieck & Co với mong muốn tạo ra dòng Champagne xứng đáng là “nữ hoàng” của mọi loại Champagne.\r\nSau khi Florens-Louis Heidsieck qua đời vào năm 1828, cháu trai của ông là Christian Heidsieck đã bắt tay cùng Henri-Guillaume Piper để đưa danh tiếng của Heidsieck & Co vượt ra ngoài khuôn khổ nước Pháp. Năm 1835, Christian Heidsieck qua đời, vợ ông tái hôn với  Henri-Guillaume Piper và  chính thức thành lập nên thương hiệu\r\nPiper Heidsieck\r\n.\r\nNăm 2011,\r\nPiper Heidsieck\r\nđược Tập đoàn EPI mua lại và chịu sự quản lý của gia đình Descours kể từ đó.', '2025-12-18 21:47:17', NULL, 0, 95, NULL);
INSERT INTO `products` (`id`, `product_name`, `slug`, `type_id`, `price`, `capacity`, `alcohol`, `origin`, `manufacturer_id`, `category_id`, `detail`, `create_at`, `update_at`, `is_delete`, `quantity`, `status`) VALUES ('VT/0278', 'Rượu Sâm Panh Champagne Piper-Heidsieck Brut 9L', 'ruou-sam-panh-champagne-piper-heidsieck-brut-9l', 2, 48620000.00, '3L', 12, 'Pháp', 49, 11, 'Quy trình sản xuất rượu Champagne Piper-Heidsieck Brut\r\nChampagne Piper-Heidsieck Brut\r\nlà thành quả pha trộn từ thành phần nho đỏ Pinot Noir, bổ sung thêm nho Pinot Meunier và Chardonnay trồng tại hơn 100 crus chất lượng nhất tại vùng Champagne của nhà sản xuất\r\nPiper-Heidsieck\r\n.\r\nNho được lựa chọn hoàn toàn thủ công để chuyển đến quá trình lên men truyền thống và lên men malolactic trong thùng. Một lượng lớn rượu vang dự trữ từ các niên vụ trước đó sẽ được đưa vào hỗn hợp rượu trong suốt quá trình pha trộn, với tỷ lệ được quyết định bởi đội ngũ sản xuất dày dặn kinh nghiệm tại Piper-Heidsieck.\r\nThành phần rượu vang dự trữ cũng chính là chìa khoá giúp đảm bảo tính nhất quán về phong cách và hương vị rượu\r\nChampagne Piper-Heidsieck\r\nqua từng năm. Trung bình mỗi chai\r\nChampagne Piper-Heidsieck Brut\r\nsẽ được ủ thêm tối thiểu 24 tháng trong chai nhằm đạt đến hương vị hoàn chỉnh nhất và sẵn sàng bán ra thị trường.', '2025-12-18 21:47:17', NULL, 0, 67, NULL);
INSERT INTO `products` (`id`, `product_name`, `slug`, `type_id`, `price`, `capacity`, `alcohol`, `origin`, `manufacturer_id`, `category_id`, `detail`, `create_at`, `update_at`, `is_delete`, `quantity`, `status`) VALUES ('VT/0277-1.5L-LUMINOUS', 'Rượu Sâm Panh Champagne Piper-Heidsieck Brut Luminous – 1.5L', 'ruou-sam-panh-champagne-piper-heidsieck-brut-luminous-15l', 2, 5566000.00, '1.5L', 12, 'Pháp', 49, 11, 'Thương hiệu Champagne Piper-Heidsieck\r\nPiper-Heidsieck\r\nlà nhà làm\r\nChampagne\r\nnổi tiếng với lịch sử làm vang lừng lẫy từ năm 1785 tại Pháp. Thuơng hiệu nổi tiếng với phương pháp pha trộn nho độc đáo, được ra đời từ sự kết hợp giữa ba giống nho Chardonnay, Pinot Noir và Pinot Meunier.\r\nThương hiệu hiện là tài sản của công ty Vranken-Pommery Monopole, có trụ sở đặt tại Reims và nằm dưới quyền quản lý của winemaker danh tiếng Régis Camus. Régis đã gắn bó với\r\nPiper-Heidsieck\r\ntừ cuối những năm 1990 và là người có công lớn trong việc đưa danh tiếng của\r\nChampagne Piper-Heidsieck\r\nngày một vươn xa nhờ những kỹ thuật làm vang đầy sáng tạo và đổi mới của mình.\r\nPiper-Heidsieck\r\nhiện là một trong những thương hiệu Champagne được ngưỡng mộ nhất trên thế giới với vô số giải thưởng minh chứng cho chất lượng vượt trội.', '2025-12-18 21:47:17', NULL, 0, 51, NULL);
INSERT INTO `products` (`id`, `product_name`, `slug`, `type_id`, `price`, `capacity`, `alcohol`, `origin`, `manufacturer_id`, `category_id`, `detail`, `create_at`, `update_at`, `is_delete`, `quantity`, `status`) VALUES ('VD/1253', 'Rượu Sâm Panh Champagne Piper-Heidsieck Brut Rosé', 'ruou-sam-panh-champagne-piper-heidsieck-brut-rose', 2, 3630000.00, '750ML', 12, 'Pháp', 49, 11, 'Thương hiệu rượu Champagne Piper-Heidsieck\r\nPiper-Heidsieck\r\nlà thương hiệu Champagne nổi tiếng được Florens-Louis Heidsieck thành lập từ năm 1785 tại Reims, Pháp. Khát vọng tạo nên một “Dòng rượu của Nữ hoàng” là tiền đề khiến Florens quyết định tặng Nữ hoàng Pháp Marie Antoinette rượu vang của mình và được bà ưu ái yêu thích ngay từ ngụm thử nếm đầu tiên.\r\nNữ hoàng nhanh chóng trở thành đại sứ thương hiệu đầu tiên của\r\nChampagne Piper-Heidsieck\r\n. Sau khi Florens qua đời vào năm 1828, thương hiệu được quản lý bởi cháu trai của Florens là Christian Heidsieck và Guillaume Piper.\r\nNăm 2011, thương hiệu được Tập đoàn EPI do Christopher Descours làm chủ mua lại. Dưới sự dẫn dắt và nguồn vốn đầu tư đáng kể của Christopher, vườn nho và hầm rượu tại\r\nPiper-Heidsieck\r\nđã có sự cải thiện đáng kể, dẫn đến sự tăng trưởng doanh số nhanh chóng sau nhiều thập kỷ suy giảm.\r\nThương hiệu hiện vinh dự có mặt ở hơn 100 quốc gia, vùng lãnh thổ và là Nhà sản xuất Champagne được trao nhiều giải thưởng nhất thế kỷ, với tổng cộng hơn 275 huy chương từng được ghi nhận.', '2025-12-18 21:47:17', NULL, 0, 54, NULL);
INSERT INTO `products` (`id`, `product_name`, `slug`, `type_id`, `price`, `capacity`, `alcohol`, `origin`, `manufacturer_id`, `category_id`, `detail`, `create_at`, `update_at`, `is_delete`, `quantity`, `status`) VALUES ('VT/0276-14', 'Rượu Sâm Panh Champagne Piper-Heidsieck Brut Vintage 2014', 'ruou-sam-panh-champagne-piper-heidsieck-brut-vintage-2014', 2, 2759000.00, '750ML', 12, 'Pháp', 49, 11, 'Thương hiệu Champagne Piper-Heidsieck\r\nFlorens-Louis Heidsieck thành lập thương hiệu\r\nChampagne Piper-Heidsieck\r\ntừ năm 1785. Sau khi Florens qua đời vào năm 1828, cháu trai của ông là Christian Heidsieck đã hợp tác cùng Guillaume Piper để phát triển thương hiệu\r\nPiper-Heidsieck\r\nngày một lớn mạnh.\r\nNăm 2011 đánh dấu cột mốc quan trọng với\r\nPiper-Heidsieck\r\n, sau khi thương hiệu được tập đoàn EPI do Christopher Descours đứng đầu thu mua lại. Nỗ lực đưa danh tiếng và chất lượng\r\nChampagne Piper-Heidsieck\r\ntrở về thời hoàng kim của Christopher đã dần có tác dụng, thể hiện qua sự tăng trưởng doanh thu nhờ vào khoản đầu tư khổng lồ vào việc mở rộng quy mô vườn nho lẫn hiện đại hoá hầm rượu và nhà máy sản xuất rượu.\r\nNgày nay,\r\nPiper-Heidsieck\r\nhoạt động chung với thương hiệu\r\nChampagne Charles Heidsieck\r\ntại một cơ sở sản xuất rượu vang hiện đại ở vùng ngoại ô phía Nam của Reims, Pháp, duy trì tên tuổi của một trong những nhà làm\r\nChampagne\r\nxuất sắc nhất trên thế giới.', '2025-12-18 21:47:17', NULL, 0, 15, NULL);
INSERT INTO `products` (`id`, `product_name`, `slug`, `type_id`, `price`, `capacity`, `alcohol`, `origin`, `manufacturer_id`, `category_id`, `detail`, `create_at`, `update_at`, `is_delete`, `quantity`, `status`) VALUES ('VT/0481', 'Rượu Sâm Panh Champagne Ruinart Blanc De Blancs', 'ruou-sam-panh-champagne-ruinart-blanc-de-blancs', 2, 7865000.00, '750ML', 12.5, 'Pháp', 50, 11, 'Ruinart Blanc De Blancs – Từ thương hiệu champagne lâu đời nhất thế giới\r\nLà thương hiệu\r\nChampagne\r\nđầu tiên được thành lập vào năm 1729,\r\nRuinart\r\nđược lấy cảm hứng từ người có tầm nhìn xa trông rộng – Tu sĩ Dom Thierry Ruinart. Vào ngày 1/9/1729, tại Reims, trung tâm vùng Champagne, Nicolas Ruinart – Cháu trai của Dom Thierry Ruinart, đã thành lập\r\nMaison Ruinart\r\n, công ty sản xuất champagne đầu tiên trên thế giới. Tầm nhìn của Dom Thierry Ruinart đã truyền cảm hứng cho một sáng kiến ​​​​làm nên lịch sử.\r\nHầm đá phấn của\r\nRuinart\r\nlà những di tích lịch sử với kiến ​​trúc tuyệt vời, được UNESCO công nhận là Di sản Thế giới vào tháng 7/2015. Những hầm rượu giống như nhà thờ nằm sâu 40 mét dưới lòng đất là nơi những chai champagne ngủ yên để chờ đợi sự bùng nổ hương vị. Với Ruinart, giống nho trắng Chardonnay mang tính biểu tượng. Nho được canh tác trên thổ nhưỡng giàu đất đá vôi tốt nhất của Côte des Blancs và Montagne de Reims, đem lại chất vị quý phái, tinh khiết và hương thơm tươi mát. Dòng Blanc de Blancs từ Ruinart là một huyền thoại được săn đón trên khắp thế giới.', '2025-12-18 21:47:17', NULL, 0, 14, NULL);
INSERT INTO `products` (`id`, `product_name`, `slug`, `type_id`, `price`, `capacity`, `alcohol`, `origin`, `manufacturer_id`, `category_id`, `detail`, `create_at`, `update_at`, `is_delete`, `quantity`, `status`) VALUES ('VT/0057-08', 'Rượu Sâm Panh Champagne Piper-Heidsieck Rare Brut Millésime 2008', 'ruou-sam-panh-champagne-piper-heidsieck-rare-brut-millesime-2008', 2, 9383000.00, '750ML', 12, 'Pháp', 49, 11, 'Rượu Champagne Piper-Heidsieck Rare Brut Millésime\r\nPiper-Heidsieck Rare\r\nlà tuyệt tác Champagne được tạo nên bởi tâm huyết của Régis Camus – bậc thầy pha trộn huyền thoại vùng\r\nChampagne\r\n. Một dòng vang đại diện cho sự hòa quyện nhịp nhàng giữa sức sáng tạo của nhà làm vang xuất sắc và những gì tinh túy nhất của thổ nhưỡng vùng Champagne.\r\nCâu chuyện về Rare bắt đầu vào mùa hè năm 1976, khi Pháp và vùng Champagne phải hứng chịu một đợt nắng nóng chưa từng có tiền lệ. Đợt nắng nóng này buộc nhóm sản xuất rượu vang tại\r\nPiper-Heidsieck\r\nphải đặt ra câu hỏi liệu họ có thể tạo ra một dòng rượu Champagne dưới điều kiện thời tiết khắc nghiệt không.\r\nViệc chế ngự những khó khăn về tự nhiên không phải là một nhiệm vụ dễ dàng, tuy nhiên các nhà nghiên cứu đã thành công. Dòng Champagne đầu tiên được nhóm nghiên cứu đặt tên là Rare. Hiện có 11 niên vụ Champagne Piper-Heidsieck Rare Brut Millésime được đưa ra thị trường, bao gồm các niên vụ 1976, 1979, 1985, 1988, 1990, 1998, 1999, 2002, 2006, 2007 và 2008.', '2025-12-18 21:47:17', NULL, 0, 23, NULL);
INSERT INTO `products` (`id`, `product_name`, `slug`, `type_id`, `price`, `capacity`, `alcohol`, `origin`, `manufacturer_id`, `category_id`, `detail`, `create_at`, `update_at`, `is_delete`, `quantity`, `status`) VALUES ('VT/0482', 'Rượu Sâm Panh Champagne Ruinart Brut', 'ruou-sam-panh-champagne-ruinart-brut', 2, 5808000.00, '750ML', 12, 'Pháp', 50, 11, 'Ruinart Brut – Hương vị Champagne đẳng cấp\r\nRuinart\r\nlà thương hiệu\r\nChampagne\r\nlâu đời nhất thế giới, được thành lập vào năm 1729 tại Reims, trung tâm vùng Champagne. Với triết lý luôn theo đuổi chất lượng xuất sắc, đội ngũ Ruinart đã làm nên những dòng champagne mang dấu ấn riêng với hương vị tuyệt hảo và hình dáng chai đặc biệt.\r\nNhững dòng champagne từ giống nho Chardonnay được ngâm ủ trong hầm đá phấn của Ruinart: 3 năm đối với dòng non-vintage và 9 – 10 năm đối với Dom Ruinart. Nhiệt độ trong hầm được giữ ở mức 10 – 12°C quanh năm với độ ẩm hoàn hảo, không có chuyển động và bao trùm trong bóng tối để mang lại điều kiện ủ rượu tốt nhất.\r\nChampagne Ruinart Brut\r\nlà một dòng champagne chất lượng từ thương hiệu này, được yêu thích trên khắp thế giới. Ông Frédéric Panaïotis – Cellar Master của Maison Ruinart chia sẻ: “Hàng năm, chúng tôi phải làm lại công thức của Ruinart Brut để duy trì hương vị của nó, đồng thời bổ sung thêm một chút đổi mới đương đại”', '2025-12-18 21:47:17', NULL, 0, 72, NULL);
INSERT INTO `products` (`id`, `product_name`, `slug`, `type_id`, `price`, `capacity`, `alcohol`, `origin`, `manufacturer_id`, `category_id`, `detail`, `create_at`, `update_at`, `is_delete`, `quantity`, `status`) VALUES ('VD/1233', 'Rượu Sâm Panh Champagne Ruinart Rosé', 'ruou-sam-panh-champagne-ruinart-rose', 2, 6160000.00, '750ML', 12.5, 'Pháp', 50, 11, '', '2025-12-18 21:47:17', NULL, 0, 92, NULL);
INSERT INTO `products` (`id`, `product_name`, `slug`, `type_id`, `price`, `capacity`, `alcohol`, `origin`, `manufacturer_id`, `category_id`, `detail`, `create_at`, `update_at`, `is_delete`, `quantity`, `status`) VALUES ('VT/0335', 'Rượu Sâm Panh Champagne Piper-Heidsieck Essentiel Blanc De Blancs', 'ruou-sam-panh-champagne-piper-heidsieck-essentiel-blanc-de-blancs', 2, 2517000.00, '750ML', 12, 'Pháp', 49, 11, 'Thương hiệu Champagne Piper-Heidsieck\r\nPiper-Heidsieck\r\nlà thương hiệu Champagne danh tiếng được thành lập từ năm 1785 tại Reims, Pháp. Thương hiệu chính thức được biết đến với tên gọi hiện tại sau cuộc hôn nhân của Madame Heidsieck và Henri-Guillaume Piper vào năm 1838, nhưng sau đó nhanh chóng rơi vào thời kỳ suy tàn trong hàng thập kỷ tiếp theo.\r\nThương hiệu được hồi sinh vào giữa thế kỷ 20, cụ thể là năm 2011, sau khi Tập đoàn EPI do Christopher Descours làm chủ quyết định mua lại\r\nPiper-Heidsieck\r\nvới quyết tâm đưa Piper-Heidsieck trở thành một trong những nhà làm\r\nChampagne\r\nnổi tiếng nhất tại Champagne, Pháp.\r\nPiper-Heidsieck\r\nhiện là một trong những nhà sản xuất\r\nChampagne\r\nđược trao nhiều giải thưởng nhất thế kỷ, đặc trưng với các dòng Champagne có cấu trúc, nổi bật với hương trái cây hấp dẫn.', '2025-12-18 21:47:17', NULL, 0, 43, NULL);
INSERT INTO `products` (`id`, `product_name`, `slug`, `type_id`, `price`, `capacity`, `alcohol`, `origin`, `manufacturer_id`, `category_id`, `detail`, `create_at`, `update_at`, `is_delete`, `quantity`, `status`) VALUES ('VT/0279', 'Rượu Sâm Panh Champagne Piper-Heidsieck Brut, 12L', 'ruou-sam-panh-champagne-piper-heidsieck-brut-12l', 2, 64900000.00, '12L', 0, 'Pháp', 49, 1, '', '2025-12-18 21:47:17', NULL, 0, 38, NULL);
INSERT INTO `products` (`id`, `product_name`, `slug`, `type_id`, `price`, `capacity`, `alcohol`, `origin`, `manufacturer_id`, `category_id`, `detail`, `create_at`, `update_at`, `is_delete`, `quantity`, `status`) VALUES ('VT/0232-16', 'Rượu Sâm Panh Champagne Aÿ Grand Cru ARGONNE 2016', 'ruou-sam-panh-champagne-a-grand-cru-argonne-2016', 2, 22990000.00, '750ML', 12, 'Pháp', 17, 1, '', '2025-12-18 21:47:17', NULL, 0, 59, NULL);
INSERT INTO `products` (`id`, `product_name`, `slug`, `type_id`, `price`, `capacity`, `alcohol`, `origin`, `manufacturer_id`, `category_id`, `detail`, `create_at`, `update_at`, `is_delete`, `quantity`, `status`) VALUES ('VT/0584', 'Rượu Sâm Panh Champagne Alfred Gratien Blanc de Blancs 2015', 'ruou-sam-panh-champagne-alfred-gratien-blanc-de-blancs-2015', 2, 3860000.00, '750ML', 11, 'Pháp', 28, 11, 'Champagne Alfred Gratien- Sự Kết Hợp Giữa Truyền Thống và Hiện Đại\r\nNhà làm rượu\r\nAlfred Gratien\r\nđã kết hợp tinh hoa của truyền thống và sự hiện đại trong quá trình sản xuất Champagne. Họ tiếp tục sử dụng các phương pháp truyền thống như lên men trong thùng gỗ sồi và sử dụng chai thủ công để tạo ra những chai rượu độc đáo. Điều này tạo ra sự độc đáo và cá tính riêng biệt cho champagne Alfred Gratien.\r\nNiên vụ 2015 được xem là một năm thu hoạch xuất sắc tại Champagne, và nhà sản xuất\r\nChampagne Alfred Gratien\r\nđã tận dụng cơ hội này để tạo ra một chai rượu Blanc de Blancs đỉnh cao. Được làm từ 100% nho Chardonnay,\r\nChampagne Alfred Gratien Blanc de Blancs\r\nđã thể hiện trọn vẹn sự tinh tế và sự thanh khiết của giống nho này.', '2025-12-18 21:47:17', NULL, 0, 80, NULL);
INSERT INTO `products` (`id`, `product_name`, `slug`, `type_id`, `price`, `capacity`, `alcohol`, `origin`, `manufacturer_id`, `category_id`, `detail`, `create_at`, `update_at`, `is_delete`, `quantity`, `status`) VALUES ('VD/1471', 'Rượu Sâm Panh Champagne Alfred Gratien Brut Rosé', 'ruou-sam-panh-champagne-alfred-gratien-brut-rose', 2, 1983000.00, '750ML', 12.5, 'Pháp', 28, 11, 'Champagne Alfred Gratien – Di sản champagne thủ công danh tiếng\r\nChampagne Alfred Gratien\r\nlà một trong những cái tên đặc biệt ở vùng Champagne nước Pháp. Rượu champagne từ Alfred Gratien được làm thủ công để đảm bảo chất lượng và tính nhất quán. Cách trung tâm thị trấn nhộn nhịp của Epernay vài dặm, sâu trong lòng vườn nho Champagne là những hầm rượu của Alfred Gratien.\r\nChính tại đây, trên đường Rue Maurice Cerveaux, Alfred Gratien đã thành lập công việc kinh doanh của mình và tạo ra những dòng champagne đầu tiên vào năm 1864. Trong hơn một thế kỷ, rượu\r\nChampagne Alfred Gratien\r\nvẫn luôn là di sản của gia đình, được duy trì nhờ chuyên môn và bí quyết của những người sáng lập.\r\nTrải qua bốn thế hệ, từ 2007, di sản champagne Alfred Gratien được Nicolas điều hành. Nicolas là hiện thân của ký ức sống động về điền trang Alfred Gratien và những chai champagne hảo hạng, chinh phục những tín đồ yêu rượu vang cao cấp.', '2025-12-18 21:47:17', NULL, 0, 26, NULL);
INSERT INTO `products` (`id`, `product_name`, `slug`, `type_id`, `price`, `capacity`, `alcohol`, `origin`, `manufacturer_id`, `category_id`, `detail`, `create_at`, `update_at`, `is_delete`, `quantity`, `status`) VALUES ('VT/0583', 'Rượu Sâm Panh Champagne Alfred Gratien Brut', 'ruou-sam-panh-champagne-alfred-gratien-brut', 2, 1983000.00, '750ML', 12.5, 'Pháp', 28, 11, 'Champagne thủ công Alfred Gratien\r\nNgoài việc ủ rượu trong khoảng 1000 thùng gỗ trong hầm rượu, các dòng rượu vang từ\r\nChampagne Alfred Gratien\r\nkhông trải qua quá trình lên men malolactic. Sự lựa chọn này bảo tồn đặc tính nguyên bản của trái cây và sự sống động phù hợp với rượu vang được ủ lâu năm.\r\nĐối với những dòng rượu champagne cổ điển của mình, gia đình\r\nAlfred Gratien\r\nluôn chọn cách đóng nắp kiểu cũ dưới nút chai. Nicolas Jaeger giải thích “tính thấm của nút chai và tính linh hoạt của nó khuyến khích sự phát triển của các nguồn cung cấp oxy vi mô, cần thiết cho sự phát triển tốt của rượu, đồng thời duy trì độ tươi mới.\r\nThời gian lưu trữ trong hầm phấn là giai đoạn quyết định. Hơn 1.300.000 chai champagne được lưu trữ trong hầm phấn yên tĩnh, chờ ngày xuất xưởng để chinh phục tín đồ yêu vang bằng chất lượng tuyệt hảo.', '2025-12-18 21:47:17', NULL, 0, 86, NULL);
INSERT INTO `products` (`id`, `product_name`, `slug`, `type_id`, `price`, `capacity`, `alcohol`, `origin`, `manufacturer_id`, `category_id`, `detail`, `create_at`, `update_at`, `is_delete`, `quantity`, `status`) VALUES ('VT/0585', 'Rượu Sâm Panh Champagne Alfred Gratien Cuvée Millesime 2015', 'ruou-sam-panh-champagne-alfred-gratien-cuvee-millesime-2015', 2, 1983000.00, '750ML', 12.5, 'Pháp', 28, 11, 'Champagne Alfred Gratien – Di sản champagne thủ công danh tiếng\r\nChampagne Alfred Gratien\r\nlà một trong những cái tên đặc biệt ở vùng Champagne nước Pháp. Rượu champagne từ Alfred Gratien được làm thủ công để đảm bảo chất lượng và tính nhất quán. Cách trung tâm thị trấn nhộn nhịp của Epernay vài dặm, sâu trong lòng vườn nho Champagne là những hầm rượu của Alfred Gratien.\r\nChính tại đây, trên đường Rue Maurice Cerveaux,\r\nAlfred Gratien\r\nđã thành lập công việc kinh doanh của mình và tạo ra những dòng champagne đầu tiên vào năm 1864. Trong hơn một thế kỷ, rượu champagne Alfred Gratien vẫn luôn là di sản của gia đình, được duy trì nhờ chuyên môn và bí quyết của những người sáng lập.\r\nTrải qua bốn thế hệ, từ 2007, di sản\r\nChampagne Alfred Gratien\r\nđược Nicolas điều hành. Nicolas là hiện thân của ký ức sống động về điền trang Alfred Gratien và những chai champagne hảo hạng, chinh phục những tín đồ yêu rượu vang cao cấp.', '2025-12-18 21:47:17', NULL, 0, 54, NULL);
INSERT INTO `products` (`id`, `product_name`, `slug`, `type_id`, `price`, `capacity`, `alcohol`, `origin`, `manufacturer_id`, `category_id`, `detail`, `create_at`, `update_at`, `is_delete`, `quantity`, `status`) VALUES ('VT/0586', 'Rượu Sâm Panh Champagne Alfred Gratien Cuvée Paradis 2015', 'ruou-sam-panh-champagne-alfred-gratien-cuvee-paradis-2015', 2, 5990000.00, '750ML', 12.5, 'Pháp', 28, 11, 'Từ nhà sản xuất Alfred Gratien – Di sản gia tộc nhiều thế hệ\r\nChampagne Alfred Gratien\r\nlà một trong những cái tên đặc biệt ở vùng Champagne nước Pháp. Rượu champagne từ\r\nAlfred Gratien\r\nđược làm thủ công để đảm bảo chất lượng và tính nhất quán. Cách trung tâm thị trấn nhộn nhịp của Epernay vài dặm, sâu trong lòng vườn nho Champagne là những hầm rượu của Alfred Gratien.\r\nChính tại đây, trên đường Rue Maurice Cerveaux,\r\nAlfred Gratien\r\nđã thành lập công việc kinh doanh của mình và tạo ra những dòng champagne đầu tiên vào năm 1864. Trong hơn một thế kỷ, rượu\r\nChampagne Alfred Gratien\r\nvẫn luôn là di sản của gia đình, được duy trì nhờ chuyên môn và bí quyết của những người sáng lập.\r\nTrải qua bốn thế hệ, từ 2007, di sản\r\nChampagne Alfred Gratien\r\nđược Nicolas điều hành. Nicolas là hiện thân của ký ức sống động về điền trang Alfred Gratien và những chai champagne hảo hạng, chinh phục những tín đồ yêu rượu vang cao cấp.', '2025-12-18 21:47:17', NULL, 0, 11, NULL);
INSERT INTO `products` (`id`, `product_name`, `slug`, `type_id`, `price`, `capacity`, `alcohol`, `origin`, `manufacturer_id`, `category_id`, `detail`, `create_at`, `update_at`, `is_delete`, `quantity`, `status`) VALUES ('VT/0489', 'Rượu Sâm Panh Champagne Beaumont Des Crayères Fleur De Prestige Blanc Millésimé Brut 2012', 'ruou-sam-panh-champagne-beaumont-des-crayeres-fleur-de-prestige-blanc-millesime-brut-2012', 2, 1803000.00, '750ML', 12, 'Pháp', 51, 11, 'Khám phá thổ nhưỡng và vườn nho Maison Beaumont des Crayères\r\nMaison Beaumont des Crayères\r\ntọa lạc tại thị trấn Mardeuil, trung tâm những ngọn đồi của Thung lũng Marne tại khu vực Champagne nước Pháp. Được trồng trên vùng đất có nhiều phấn, vườn nho của điền trang được trồng chủ yếu giống nho Meunier, một giống nho mà họ đã khám phá ra những bí quyết chăm sóc và phát triển tầng hương quyến rũ.\r\nQuan tâm đến việc bảo tồn di sản Champagne, điền trang\r\nBeaumont des Crayères\r\ntừ lâu đã áp dụng các nguyên tắc trồng nho hợp lý và bền vững. Mỗi thế hệ nhà sản xuất rượu vang đều cam kết tôn trọng, bảo vệ đất đai, cây nho và môi trường của họ.\r\nTriết lý làm vang tôn trọng môi trường sâu sắc của\r\nBeaumont des Crayères\r\nđã truyền cảm hứng cho nhiều nhà sản xuất, được ghi nhận và khen thưởng bằng việc ghi danh Coteaux, Maisons et Caves de Champagne vào danh sách Di sản Thế giới của UNESCO.', '2025-12-18 21:47:17', NULL, 0, 93, NULL);
