INSERT INTO `products` (`id`, `product_name`, `slug`, `type_id`, `price`, `capacity`, `alcohol`, `origin`, `manufacturer_id`, `category_id`, `detail`, `create_at`, `update_at`, `is_delete`, `quantity`, `status`) VALUES ('VD/1311-04', 'Rượu Vang Đỏ Quintarelli Giuseppe Recioto Della Valpolicella Classico 2004', 'ruou-vang-do-quintarelli-giuseppe-recioto-della-valpolicella-classico-2004', 1, 17380000.00, '750ML', 15.5, 'Ý', 62, 30, 'Quintarelli Giuseppe – Người nghệ sĩ tài ba suốt đời đi tìm cái đẹp\r\nThương hiệu\r\nQuintarelli Giuseppe\r\ncó bề dày lịch sử hơn 100 năm, khởi đầu sự nghiệp làm vang lần đầu tiên tại Figari sau đó năm 1924 tại Negar trung tâm của khu vực Valpolicella. Quintarelli được mệnh danh là ảo thuật gia lừng danh tại Valpolicella, bậc thầy của những dòng vang trứ danh Amarone hay Recioto.\r\nTheo đuổi chủ nghĩa truyền thống song ông không ngần ngại đổi mới và sáng tạo, những dự án sản xuất vang trắng được thực hiện tại Valpolicella, kết hợp khéo léo giữa giống nho địa phương Corvina cùng Cabernet Sauvignon và Cabernet Franc tạo ra Primo Fiore.\r\nBên cạnh đó không thể không nhắc đến ngôi sao Alzero, là kết quả của sự giao thoa giữa truyền thống và hiện đại, sử dụng kỹ thuật sấy khô tạo nên hương vị phức hợp đến lạ kỳ.\r\nQuintarelli\r\nđược nhớ đến với công lao to lớn khi là người đầu tiên thử nghiệm trồng giống nho Nebbiolo tại Valpolicella.\r\nRượu vang Quintarelli\r\nluôn được giới mộ điệu săn đón và sẵn sàng chi trả khoản tiền lớn để sở hữu thứ “vàng ròng” quý giá. Sản lượng nho luôn được giữ ở mức cực thấp nhằm tối ưu hóa chất lượng vang, trải qua kỹ thuật appassimento hay sấy khô truyền thống đã tạo ra những dòng vang hảo hạng với chất vị cô đọng, ngọt ngào và khả năng trữ hầm trong nhiều năm.', '2025-12-18 21:47:17', NULL, 0, 83, NULL);
INSERT INTO `products` (`id`, `product_name`, `slug`, `type_id`, `price`, `capacity`, `alcohol`, `origin`, `manufacturer_id`, `category_id`, `detail`, `create_at`, `update_at`, `is_delete`, `quantity`, `status`) VALUES ('VD/1074-18', 'Rượu Vang Đỏ Robert Mondavi Winery Cabernet Sauvignon Reserve 2018', 'ruou-vang-do-robert-mondavi-winery-cabernet-sauvignon-reserve-2018', 1, 7502000.00, '750ML', 14.5, 'Mỹ', 22, 13, 'Quy trình sản xuất Robert Mondavi Cabernet Sauvignon Reserve 2018\r\nRượu vang Robert Mondavi Winery Cabernet Sauvignon Reserve 2018\r\nđược sản xuất từ 100% nho đỏ Cabernet Sauvignon. Nho được thu hoạch hoàn toàn thủ công trong các thùng nhỏ và được phân loại tỉ mỉ trong hầm chứa.\r\nCác chùm được tuyển chọn sau đó sẽ được chuyển tới các thùng gồ sồi của Pháp để ngâm lạnh và lên men lần một kéo dài trong khoảng một tháng để chiết xuất tối đa vị chát mềm mại và độ phức tạp của nho.  Quá trình lên men malolactic sẽ được thực hiện trong thùng gỗ sồi Pháp mới 100%, trước khi bắt đầu quá trình ủ rượu kéo dài 19 tháng. Đội ngũ chuyên gia tại hầm rượu sẽ thực hiện hàng loạt cuộc thử nếm trong suốt thời gian diễn ra quá trình ủ rượu, nhằm đảm bảo rượu chạm tới hương vị hoàn hảo nhất trước khi bày bán ra thị trường.', '2025-12-18 21:47:17', NULL, 0, 100, NULL);
INSERT INTO `products` (`id`, `product_name`, `slug`, `type_id`, `price`, `capacity`, `alcohol`, `origin`, `manufacturer_id`, `category_id`, `detail`, `create_at`, `update_at`, `is_delete`, `quantity`, `status`) VALUES ('VD/1074-19', 'Rượu Vang Đỏ Robert Mondavi Winery Cabernet Sauvignon Reserve 2019', 'ruou-vang-do-robert-mondavi-winery-cabernet-sauvignon-reserve-2019', 1, 7502000.00, '750ML', 14.5, 'Mỹ', 22, 13, '', '2025-12-18 21:47:17', NULL, 0, 51, NULL);
INSERT INTO `products` (`id`, `product_name`, `slug`, `type_id`, `price`, `capacity`, `alcohol`, `origin`, `manufacturer_id`, `category_id`, `detail`, `create_at`, `update_at`, `is_delete`, `quantity`, `status`) VALUES ('VD/1476-16-3L', 'Rượu vang đỏ Rubinelli Vajol Amarone Della Valpolicella Classico 2016', 'ruou-vang-do-rubinelli-vajol-amarone-della-valpolicella-classico-2016', 1, 9922000.00, '3L', 0, 'Ý', 10, 7, '', '2025-12-18 21:47:17', NULL, 0, 53, NULL);
INSERT INTO `products` (`id`, `product_name`, `slug`, `type_id`, `price`, `capacity`, `alcohol`, `origin`, `manufacturer_id`, `category_id`, `detail`, `create_at`, `update_at`, `is_delete`, `quantity`, `status`) VALUES ('VD/0796-16', 'Rượu Vang Đỏ Sandrone Barolo Aleste 2016', 'ruou-vang-do-sandrone-barolo-aleste-2016', 1, 3850000.00, '750ML', 14.5, 'Ý', 11, 8, 'Triết lý làm vang đầy sâu sắc của Luciano Sandrone\r\nĐội ngũ sản xuất của\r\nLuciano Sandrone\r\ntận tâm cống hiến và làm việc bền bỉ trong hơn 50 năm không chút mệt mỏi. Gây dựng sự nghiệp làm vang đáng tự hào từ những cây nho bản địa trên những mảnh đất có chất lượng vượt trội là cơ sở cho triết lý làm vang của Luciano, triết lý này được tiếp nối qua các thế hệ sau. Tại đây, dường như những cây nho tìm thấy mái nhà thực sự của mình, nơi mà chúng được chăm sóc, nuôi dưỡng dưới đôi bàn tay khéo léo của người thợ lành nghề.\r\nHơn nữa, để đảm bảo tạo ra hệ sinh thái bền vững và thân thiện, điền trang luôn cố gắng chỉn chu trong mọi giai đoạn sản xuất với thái độ tôn trọng tuyệt đối môi trường. Điền trang hạn chế tối đa sự can thiệp của con người tới các vườn nho, có trách nhiệm giữ gìn bảo tồn các nguồn tài nguyên thiên nhiên quý giá.', '2025-12-18 21:47:17', NULL, 0, 12, NULL);
INSERT INTO `products` (`id`, `product_name`, `slug`, `type_id`, `price`, `capacity`, `alcohol`, `origin`, `manufacturer_id`, `category_id`, `detail`, `create_at`, `update_at`, `is_delete`, `quantity`, `status`) VALUES ('VD/0796-17', 'Rượu Vang Đỏ Sandrone Barolo Aleste 2017', 'ruou-vang-do-sandrone-barolo-aleste-2017', 1, 4235000.00, '750ML', 14.5, 'Ý', 11, 8, 'Cannubi – Vườn nho Grand Cru làm nên danh tiếng cho thương hiệu Luciano Sandrone\r\nDù tên gọi có thể thay đổi theo thời gian, nhưng rượu vang đỏ Barolo từ\r\nLuciano Sandrone\r\nvẫn và sẽ luôn được biết đến với tư cách rượu vang Cannubi Boshis. Toạ lạc tại phía Bắc ngọn đồi Cannubi, đối diện với các hầm rượu của\r\nSandrone\r\n, vườn nho Cannubi với diện tích 1.9 hecta được bao phủ bởi các cây nho có tuổi đời trên 40 năm là mái nhà sản sinh nên các dòng vang đỏ hảo hạng.\r\nVị trí nằm trên sườn dốc phức tạp, hướng về phía Nam và Đông Nam mang đến cho Cannubi khả năng tiếp xúc tốt với ánh sáng mặt trời để giữ ấm cho cây nho, kết hợp với sự biến đổi đa dạng của đất, cụ thể là từ đất sét vôi đến đất cát với khả năng thoát nước tuyệt vời giúp nho phát triển những đặc tính xuất sắc nhất. Như Barbara Sandrone từng mô tả Cannubi  “giống như một con rồng đang ngủ say” đã đánh thức thổ nhưỡng phức hợp của Barolo bằng những dòng vang sang trọng và thấm đẫm tinh tuý.\r\nQuy trình sản xuất rượu vang Sandrone Barolo Aleste 2017\r\nSandrone Barolo Aleste 2017\r\nlà minh chứng rõ nét cho quy trình sản xuất công phu của thương hiệu\r\nLuciano Sandrone\r\n, bắt đầu từ công đoạn phân loại, lên men, ủ thùng.. Cụ thể, mỗi lô nho thu hoạch được tách cuống và nghiền nhẹ trước khi phủ CO2 và ngâm trong nước ấm trong khoảng một ngày. Khoảng 24 đến 36 tiếng sau đó, nho được chuyển đến lên men bằng các loại nấm men bản địa trong các thùng có nắp đậy trong 28-30 ngày, trước khi chuyển sang quá trình lên men malolactic trong các thùng gỗ sồi Pháp 500 lít. Kết thúc quá trình lên men lần 2, rượu tiếp tục được ủ thêm trong thùng gỗ trong 24 tháng, sau đó là 18 ủ trong chai để đạt hương vị sâu lắng tuyệt vời đã làm nên tên tuổi cho nhà sản xuất\r\nLuciano Sandrone\r\n.', '2025-12-18 21:47:17', NULL, 0, 100, NULL);
INSERT INTO `products` (`id`, `product_name`, `slug`, `type_id`, `price`, `capacity`, `alcohol`, `origin`, `manufacturer_id`, `category_id`, `detail`, `create_at`, `update_at`, `is_delete`, `quantity`, `status`) VALUES ('VD/0740', 'Rượu Vang Đỏ Louis Latour Château Corton Grancey Grand Cru 2015', 'ruou-vang-do-louis-latour-chateau-corton-grancey-grand-cru-2015', 1, 4392000.00, '750ML', 14, 'Pháp', 7, 5, 'Corton Grancey Grand Cru – Dòng rượu vang từ những cây nho hơn 40 năm tuổi\r\n“Grancey” là tên của chủ sở hữu cuối cùng của lâu đài nằm trên đường Corton, trước khi gia đình Latour mua lại nó vào năm 1891. Dòng rượu này do Maison Louis Latour sản xuất độc nhất và độc quyền. Nó là sự pha trộn của năm khu vực của Domaine Latour Corton Grand Cru: Bressandes, Perrières, Grèves, Clos du Roi và Chaumes, tỷ lệ của chúng thay đổi tùy theo mùa nho.\r\nTuổi trung bình của cây nho là trên 40 năm. Sau khi ủ riêng lẻ, chỉ những thùng rượu tốt nhất mới được chọn lựa để tạo ra Château Corton Gracey. Đó là dòng rượu chỉ được sản xuất nếu nho ở độ chín hoàn hảo, những dòng rượu được đánh giá là kém chất lượng sẽ được phân loại một cách có hệ thống.', '2025-12-18 21:47:17', NULL, 0, 63, NULL);
INSERT INTO `products` (`id`, `product_name`, `slug`, `type_id`, `price`, `capacity`, `alcohol`, `origin`, `manufacturer_id`, `category_id`, `detail`, `create_at`, `update_at`, `is_delete`, `quantity`, `status`) VALUES ('VD/0741', 'Rượu Vang Đỏ Louis Latour Château Corton Grancey Grand Cru 2016', 'ruou-vang-do-louis-latour-chateau-corton-grancey-grand-cru-2016', 1, 6948000.00, '750ML', 14, 'Pháp', 7, 5, 'Corton Grancey Grand Cru – Dòng rượu vang từ những cây nho hơn 40 năm tuổi\r\n“Grancey” là tên của chủ sở hữu cuối cùng của lâu đài nằm trên đường Corton, trước khi gia đình Latour mua lại nó vào năm 1891. Dòng rượu này do Maison Louis Latour sản xuất độc nhất và độc quyền. Nó là sự pha trộn của năm khu vực của Domaine Latour Corton Grand Cru: Bressandes, Perrières, Grèves, Clos du Roi và Chaumes, tỷ lệ của chúng thay đổi tùy theo mùa nho.\r\nTuổi trung bình của cây nho là trên 40 năm. Sau khi ủ riêng lẻ, chỉ những thùng rượu tốt nhất mới được chọn lựa để tạo ra Château Corton Gracey. Đó là dòng rượu chỉ được sản xuất nếu nho ở độ chín hoàn hảo, những dòng rượu được đánh giá là kém chất lượng sẽ được phân loại một cách có hệ thống.', '2025-12-18 21:47:17', NULL, 0, 15, NULL);
INSERT INTO `products` (`id`, `product_name`, `slug`, `type_id`, `price`, `capacity`, `alcohol`, `origin`, `manufacturer_id`, `category_id`, `detail`, `create_at`, `update_at`, `is_delete`, `quantity`, `status`) VALUES ('VD/0263', 'Rượu Vang Đỏ Louis Latour Corton-Perrières Grand Cru 2010', 'ruou-vang-do-louis-latour-corton-perrieres-grand-cru-2010', 1, 6256000.00, '750ML', 14, 'Pháp', 7, 5, 'Louis Latour Corton-Perrières Grand Cru – Rượu vang từ thửa ruộng Perrières\r\nPerrières Corton-Grand Cru\r\nlà một trong những thửa ruộng nổi tiếng tại vùng sản xuất rượu Bourgogne của Pháp. Đây là thửa ruộng xếp hạng\r\nGrand Cru\r\n, một trong những danh hiệu cao cấp nhất của vùng này, chỉ dành cho những thửa ruộng nho có tiềm năng sản xuất rượu vang tuyệt vời.\r\nNằm trên ngọn đồi\r\nCorton Grand Crus\r\nở độ cao 273 mét so với mực nước biển, trong một mỏ đá cũ, lô đất trồng nho “Perrières” có vị trí hoàn hảo về phía đông nam. Thổ nhưỡng đất sét màu nâu và đỏ tạo nên chất vị rượu thơm ngon và đậm đà. Những cây nho lâu năm được quản lý theo cách truyền thống bởi\r\nMaison Louis Latour\r\n.\r\nViệc cắt tỉa cẩn thận giúp việc thu hoạch muộn hơn và đảm bảo mức độ trưởng thành cũng độ phong phú cho hương vị của nho.', '2025-12-18 21:47:17', NULL, 0, 84, NULL);
INSERT INTO `products` (`id`, `product_name`, `slug`, `type_id`, `price`, `capacity`, `alcohol`, `origin`, `manufacturer_id`, `category_id`, `detail`, `create_at`, `update_at`, `is_delete`, `quantity`, `status`) VALUES ('VD/0572', 'Rượu Vang Đỏ Luce Della Vite 2006 6000ml', 'ruou-vang-do-luce-della-vite-2006-6000ml', 1, 73205000.00, '6L', 15, 'Ý', 63, 7, 'Hương vị rượu vang đỏ Luce Della Vite 2006\r\nLuce Della Vite 2006\r\nđược pha trộn từ giống nho Sangiovese và Merlot. Sau khi thu hoạch, nho được chọn lọc, lên men trong thùng thép không gì với nhiệt độ được kiểm soát chặt chẽ dưới dưới 30°C. Giai đoạn lên men kéo dài trong 12 ngày, tiếp tục ngâm ủ trong thùng gỗ sồi thủ công mới 100% suốt 18 tháng tiếp theo.\r\nLuce Della Vite 2006\r\nlà dòng rượu vang đậm đặc, nổi bật với màu tím sẫm vô cùng quyến rũ. Rượu lan tỏa hương thơm mạnh mẽ từ trái cây mọng đỏ, nổi bật với hương mận khô, dâu đen kèm theo balsamic và hương vani ngọt ngào, kết lại bằng hương của socola, lá thuốc lá, than chì và cam thảo đen. Khi thưởng thức, rượu mang đến chất vị ấm áp, mượt mà và mãnh liệt, với vị chát thanh lịch được tăng cường bởi vị chua sống động vô cùng tươi trẻ. Rượu để lại dư vị bền bỉ trong sức quyến luyến của một dòng vang đậm chất Tuscany cổ điển.', '2025-12-18 21:47:17', NULL, 0, 77, NULL);
INSERT INTO `products` (`id`, `product_name`, `slug`, `type_id`, `price`, `capacity`, `alcohol`, `origin`, `manufacturer_id`, `category_id`, `detail`, `create_at`, `update_at`, `is_delete`, `quantity`, `status`) VALUES ('VD/0573', 'Rượu Vang Đỏ Luce Della Vite 2007', 'ruou-vang-do-luce-della-vite-2007', 1, 5203000.00, '750ML', 14.5, 'Ý', 64, 7, 'Tenuta Luce – Dự án rượu vang táo bạo bậc nhất Tuscany\r\nLịch sử của\r\nTenuta Luce\r\nbắt đầu khi Vittorio Frescobaldi và Robert Mondavi – những nhà làm vang tâm huyết với kinh nghiệm hàng đầu đã bắt tay cùng thực hiện một dự án với tầm nhìn khác biệt. Chọn Montalcino, vùng đất vốn nổi tiếng với nghề trồng nho để bắt đầu dự án, hai người đàn ông vĩ đại đã đặt mục tiêu tạo ra một dòng rượu vượt ra khỏi những quy tắc truyền thống nhưng không làm mất đi bản chất gốc rễ tuyệt đẹp của thổ nhưỡng.\r\nKinh nghiệm có được từ thập niên 70 với những vườn nho Merlot cùng những đặc tính biểu hiện riêng biệt của chúng khi được trồng trên mảnh đất Montalcino là một trong những điều kiện tiên quyết quyết định sự thành công của dự án. Luce, dòng rượu bắt đầu tất cả, được coi là điểm gặp gỡ hài hòa giữa sự thanh lịch, rắn rỏi của Sangiovese và vị tròn trịa của Merlot.', '2025-12-18 21:47:17', NULL, 0, 31, NULL);
INSERT INTO `products` (`id`, `product_name`, `slug`, `type_id`, `price`, `capacity`, `alcohol`, `origin`, `manufacturer_id`, `category_id`, `detail`, `create_at`, `update_at`, `is_delete`, `quantity`, `status`) VALUES ('VD/0845-17', 'Rượu Vang Đỏ Luce Brunello Di Montalcino 2017', 'ruou-vang-do-luce-brunello-di-montalcino-2017', 1, 5989500.00, '750ML', 15, 'Ý', 64, 31, 'Quy trình sản xuất rượu vang Luce Brunello Di Montalcino\r\nTại trung tâm nhà máy của\r\nTenuta Luce\r\n, từng nhịp đập trái tim đều ghi dấu những khoảnh khắc con người trao sức sống vào trong từng làn rượu. Đối với những nhà làm vang Luce, hầm rượu là nơi vật chất phát triển và biến đổi, là nơi mà thời gian thuộc về dòng chảy của rượu vang.\r\nTrong vụ thu hoạch, những trái nho đạt điều kiện chín lý tưởng được chuyển đến hầm từ khắp các vườn nho. Giai đoạn vận chuyển cũng được chú trọng bởi sự tôn trọng dành cho sự nguyên vẹn của trái nho. Việc lựa chọn nho được thực hiện sau quá trình lên men với các loại men bản địa và ép mềm. Sau đó là thời gian để chờ đợi.\r\nHàng tuần, hàng tháng, hàng năm trôi qua chậm rãi trong phòng ủ rượu trong khi rượu được nghỉ ngơi và phát triển thành hương vị phức hợp của riêng nó. Con người lúc này trở thành một người kết nối với những gì thiên nhiên đã ban tặng, trong quá trình không ngừng tìm kiếm sự cân bằng và phát triển trong Hầm rượu. Biết chờ đợi là một nghệ thuật. Chính triết lý làm vang tỉ mỉ, kiên nhẫn đã giúp Tenuta Luce tạo nên những dòng rượu vang đẳng cấp, được giới mộ điệu săn đón.', '2025-12-18 21:47:17', NULL, 0, 20, NULL);
